import { HelpBody } from './helpContent';

/**
 * The help catalog in Spanish.
 *
 * <p>A file per language: a translation pass is then reviewable on its own, and eighteen articles
 * in five languages inline would be one literal nobody could edit without breaking a quote. A key
 * that is missing here falls back to the English body, visibly — see `bodyFor`.</p>
 */
export const ES: Readonly<Record<string, HelpBody>> = {
  'security-lane': {
    title: 'Security lane: comprobaciones adicionales de seguridad',
    whatItIs: 'Revisiones opcionales junto a las revisiones habituales de código y funcionalidad. Cada pareja combina un revisor configurado con un prompt redteam. Están desactivadas inicialmente y requieren el gate habitual.',
    why: 'Una revisión específica examina un límite de seguridad y conserva los hallazgos y sus pruebas en el historial compartido.',
    setup: 'En Settings → Security lane, marca los módulos deseados entre los 12 disponibles para cada revisor. La primera activación selecciona authz. Ajusta las etapas, el contexto, el presupuesto, el umbral y las rondas. Los módulos incluidos necesitan señales coincidentes en el código; una lista de condiciones vacía impide ejecutarlos. Los prompts están en Git bajo src_mcp/src/prompts/redteam-*.md. Edit local prompt override abre un archivo local independiente.',
    usage: 'SECURE indica una lista vacía de hallazgos. Cada hallazgo requiere Trigger, Mechanism y Consequence. Sin reproducción completa, major/blocking se limita a minor antes de combinar resultados. Las pruebas aparecen en el historial y nunca se ejecutan. Se mantienen los límites de concurrencia existentes.',
    whatCanGoWrong: 'Se necesita MCP 0.41.0 o posterior. La configuración no se envía a servidores antiguos. Se indican los prompts ausentes, los ejecutores no disponibles y los errores de configuración. Si coai.securityLane en su settings JSON está mal formado, la lane queda desactivada; la pestaña Security lane indica el error: corríjalo allí. El contexto es limitado y las omisiones se identifican; la cobertura de la entrada local sigue sin verificarse. El éxito de esta revisión no sustituye a un revisor habitual que no respondió.',
  },
  "the-settings-tab": {
    title: "El panel y la pestaña Settings",
    whatItIs: "La barra lateral es lo que está pasando ahora: **Active questions** — lo que el question consultant está respondiendo y una pregunta que espera su respuesta —, y luego **Notifications**, **Active gates** — las rondas en curso en este minuto —, **Active consultations** — las consultas que se están teniendo —, **Consultation cadence** — en qué punto está cada plan que sigue la cadencia —, **Phrases** y **Bugz**. Todo lo que se configura una vez está en la pestaña **Settings**, que abre el engranaje junto al botón de ayuda en la barra de título del panel: una pestaña para Reviewers, Chat other AIs, Consultant, Question consultant, Security lane, Prompts per round, The gate, Limits, Vendor keys, Team servers, This side y MCP server.",
    why: "Catorce secciones plegadas en una columna estrecha obligaban a pasar por diez cosas configuradas una vez para llegar a las cuatro por las que se vuelve. Las pestañas tienen los mismos controles que tenían las secciones, con el mismo efecto — solo cambió dónde se dibujan —, así que una elección hecha en una pestaña se guarda exactamente como se guardaba la misma elección en la barra lateral.",
    setup: "No hay nada que configurar. **ConnectOtherAIs: Settings** en la paleta de comandos abre la misma pestaña. Hay una por ventana: pulsar de nuevo el engranaje la trae de vuelta en lugar de abrir otra, y se abre en la pestaña en la que estuvo por última vez en esta ventana.",
    usage: "Pulse una pestaña o use el teclado: Izquierda y Derecha recorren la franja y al llegar a un extremo pasan al otro, Inicio y Fin van a la primera y a la última, y Tab sale de la franja. Cada cambio se guarda al hacerlo, como en la barra lateral, y una respuesta nueva — una versión de CLI, una lista de modelos, un precio — se muestra en cuanto llega. Ctrl+F busca en la pestaña en la que está. Los dos pares ± junto al título cambian el tamaño del texto y su tono aquí como en cualquier otra página, y la pestaña MCP server se dibuja a una vez y media su tamaño, porque se lee más de lo que se configura.\n\n**Un pequeño ? junto a un ajuste dice qué significa** cuando pasa el puntero por encima: qué hace el ajuste y por qué existe, en una frase con la que se puede actuar. Estas páginas dicen lo mismo por extenso; el ? es para el momento en que está mirando el control.",
    whatCanGoWrong: "El engranaje se ve mientras el puntero está sobre el panel o este tiene el foco, como cualquier botón de la barra de título de VS Code; la entrada de la paleta de comandos está siempre. Tras recargar la ventana, la pestaña Settings no vuelve sola: pulse otra vez el engranaje, y se abrirá en su primera pestaña, porque la pestaña en la que estaba solo se recuerda mientras vive la ventana. Una consulta en curso aparece en la barra lateral bajo **Active consultations**, no en la pestaña Consultant: la barra lateral muestra lo que pasa ahora, y en la pestaña Consultant se decide a quién se pregunta.",
  },
  "phrases": {
    title: "Phrases: las frases que deja de reescribir",
    whatItIs: "Una lista de frases que usted guarda, como botones en la sección **Phrases** del panel. Pulse una y pasa al portapapeles; la pega donde iba a escribirla, normalmente en el cuadro de Claude Code. La lista se edita en una pestaña propia: **ConnectOtherAIs: Edit phrases**.",
    why: "Algunas instrucciones se escriben varias veces al día — *haz un pull request, acéptalo, despliega, comprueba que funciona*. Volver a escribirlas no es trabajo, es fricción, y una frase reescrita de memoria es una frase que va cambiando.\n\n**Copia en lugar de escribir en el cuadro por usted, y eso fue una decisión, no un atajo.** Claude Code no tiene ninguna orden que acepte texto arbitrario: la que sí acepta un prompt solo rellena una conversación NUEVA, nunca aquella en la que usted está. Quedaba una pulsación sintética a través de la API de Windows — solo Windows, cerca de un segundo, y nunca medida en ese sentido. Un `Ctrl+V` es mejor precio que un mecanismo que puede fallar en silencio en la máquina de otra persona.",
    setup: "Abra **Edit phrases** desde la sección *Phrases* del panel o desde la paleta de comandos. Pulse **Add a phrase**, dele un nombre para el botón y escriba la frase en el cuadro grande. Todo se guarda un instante después de que deje de escribir.\n\nEl nombre es solo una etiqueta; al portapapeles va la frase misma. Deje el nombre vacío y el botón llevará la primera línea de la propia frase.",
    usage: "La sección **Phrases** muestra un botón por frase. Púlselo, pegue, siga trabajando. La lista es solo suya: nunca se envía a `coai-mcp` ni se refleja en un Team server, y es la misma lista en ambos lados con *This side* activado — una frase que usted escribió no es una propiedad de la máquina donde la escribió.\n\nUna frase se guarda exactamente como la escribió, espacios y saltos de línea incluidos: un fragmento indentado se pega indentado y un salto de línea final se queda donde usted lo puso.",
    whatCanGoWrong: "**Una frase sin texto se descarta.** El nombre es la etiqueta y el texto es la cosa, así que una fila sin nada dentro no es una frase. Una fila que usted escribió mal en `settings.json` se descarta por sí sola y el resto de la lista sigue funcionando: perder todas las frases por una equivocada sería el fallo peor.\n\n**Un guardado que no llega lo dice, y dice por qué.** La pestaña conserva lo que usted escribió y muestra el motivo del rechazo con las palabras de quien lo rechazó, en vez de redibujar la lista sin sus palabras. El motivo más frecuente es una ventana que no se ha puesto al día con una actualización: VS Code sigue conociendo solo los ajustes que registró al abrirse la ventana, así que una frase no se puede guardar hasta que la recargue — y la línea dice justo eso, con el botón que lo hace.\n\n**Nada se pulsa por usted.** La frase llega al portapapeles y se detiene ahí; pegarla, y enviarla, siguen siendo suyas.",
  },
  "notifications": {
    title: "Notifications: todo lo que la extensión le ha dicho",
    whatItIs: "Una página con todos los mensajes que ConnectOtherAIs ha mostrado en su pantalla, conservados después de que el aviso desapareciera: qué decía, cuándo, desde dónde, qué hacer al respecto y cuántas veces ha ocurrido. La sección **Notifications** del panel dice cuántos son nuevos y la abre.",
    why: "Un mensaje que usted no estaba mirando es un mensaje que nunca ocurrió. El 16-09-2026 un rol borrado a las 19:05 siguió siendo revisado durante once rondas, porque el espejo de ajustes se había detenido a las 18:27 y lo dijo exactamente una vez, en un aviso que nadie vio. Noventa minutos del día de una persona se fueron en averiguarlo. Ahora cada mensaje entra primero en un archivo y después en la pantalla, para que la respuesta a «¿qué decía?» esté en otro sitio que no sea la memoria de alguien.",
    setup: "Nada que configurar. Esta extensión escribe en `notifications.jsonl`, en la misma carpeta de datos que todo lo demás. La página también lee `server-notices.jsonl` al lado, donde escribirá el servidor MCP: esa mitad aún no está construida, así que hoy, en una instalación en uso, el archivo sencillamente no existe. Mover esa carpeta los mueve con ella.",
    usage: "La sección **Notifications** del panel dice cuántos hay desde la última vez que miró y abre la página. En ella, una pestaña por TIPO — un fallo, un rechazo, una parada, una tormenta, una pregunta que usted respondió — y una fila por cosa ocurrida, por muchas veces que haya ocurrido.\n\n**Una fila es un fallo, no una aparición.** Si algo salió mal cuatrocientas veces, eso es una fila que dice cuatrocientas, con la rapidez con que llegaron al lado. Ordene por cualquier columna; los vacíos van al final en ambos sentidos, así que un ritmo que no pudo medirse nunca sube arriba. La búsqueda encuentra cualquier palabra de la fila, incluido el propio mensaje. **Source** reduce a lo que dijo una parte de la extensión, **From** y **To** a un intervalo de tiempo, y **Clear** los quita todos de una vez. **Previous** y **Next** recorren las filas página a página.\n\nAbrir la página marca como leídos los registros que cargó. **Con un filtro puesto no marca nada** — tres filas en pantalla no deben afirmar que se leyeron tres mil — y la línea sobre la tabla dice cuál de las dos cosas está pasando. **Mark everything read** es el botón para un historial que no piensa recorrer hacia atrás.",
    whatCanGoWrong: "**Un fallo repetido está acotado y lo dice, en vez de fingir.** Una misma cosa puede registrarse mil veces en una ejecución de la ventana; a partir de ahí el archivo se detiene y la fila se lee *1000+*, nunca un número que nadie puede saber. Tres ventanas que llegan cada una a ese punto se muestran como *1000+ in each of 3 runs*, porque tres ventanas con problemas no son un incidente tres veces mayor.\n\n**La página muestra los últimos miles de registros, no el archivo.** Cuando hay más antiguos lo dice, y siguen sin leer hasta que usted vaya a ellos o pulse **Mark everything read**.\n\n**Un recuento que no pudo leerse lo dice en lugar de mostrar cero.** «Todavía no se ha escrito nada», «no se pudieron leer las notificaciones» y «nada nuevo» son tres frases distintas a propósito: una lectura rota que aparece como un cero limpio es lo que enseña a una persona a dejar de fiarse de un contador — y este existe porque a alguien se le escapó un mensaje.\n\n**Los secretos se quitan a la entrada.** Una contraseña, un token o una clave en una URL o en un mensaje de error se sustituyen antes de que la línea llegue al archivo, y el archivo conserva todo lo demás. En una misma máquina pueden existir dos carpetas de datos, una para Windows y otra para WSL; la página nombra la que está leyendo, porque «está vacía» y «está mirando la otra» son problemas distintos.",
  },
  "your-own-roles": {
    title: "Roles propios: revisar algo que no es código",
    whatItIs: "Un rol de revisión es un revisor con una pregunta. Este producto trae cinco: crítica del plan, convenciones, arquitectura, seguridad y fiabilidad, rendimiento y UX-DX. **Los roles que usted añade son suyos**, con nombres en su idioma y las preguntas que usted quiere que se hagan.\n\nLa puerta a su alrededor no cambia. Las mismas rondas, el mismo umbral, los mismos hallazgos con las mismas categorías, el mismo veredicto. Lo que cambia es qué se le pregunta a un revisor, y eso es el prompt que usted escribe.",
    why: "Los cinco que vienen de fábrica son los cinco que quiere un programador. Quien contrasta requisitos con una especificación, lee currículos o repasa la descripción de un producto antes de publicarla necesita otra pregunta, y nadie puede preverlas todas de antemano. Por eso es una lista que usted edita y no una lista que nosotros entregamos.",
    setup: "**Edit roles…** en *Prompts per round* abre la página de roles. Añada un rol, póngale nombre y escriba su prompt general: la pregunta que se hace cuando no se ha elegido otra cosa. Añada más prompts para preguntas más estrechas; en *Prompts per round* se ofrecen uno por ronda.\n\nLos cinco roles de fábrica están en esa misma página. Puede reescribir el texto de cualquiera de sus prompts y añadirles prompts propios; no puede renombrarlos, moverlos a la otra etapa ni borrar lo que traen, porque sus nombres ya son claves en sus ajustes, en las sesiones abiertas y en cada ronda registrada, y el servidor de revisión no lee ninguna de esas cosas de su configuración: una página que le dejara cambiarlas mostraría algo que ninguna ronda hará.\n\n**El identificador se genera por usted** y se muestra bajo el nombre. Así se llama su rol en el ajuste, en el archivo de sesión y en la base de datos, de modo que después no cambia: renombre el rol tantas veces como quiera.\n\n**Como mucho cinco roles activos por etapa.** Un sexto no se puede marcar; desactive uno antes. Un rol que añada nace desactivado —aún no tiene pregunta— y no se puede activar mientras haya cinco activos: lo que la página muestra es lo que se ejecutará. Un rol desactivado permanece en esta página con todo lo que usted escribió en él.",
    usage: "Todo en la página se guarda un momento después de que deje de escribir. El TEXTO de un prompt se escribe en un archivo junto a sus demás datos de coai, que es de donde el servidor siempre ha leído las sustituciones de prompts: un prompt reescrito sobrevive a una actualización, y borrar el archivo devuelve lo que el producto trae.\n\n**Un rol para algo que no es una tarea de programación** lo ejecuta `review_document`, la puerta de documentos, cuando su etapa es *Code review*: lee un DOCUMENTO en lugar de un diff, y la página lo archiva bajo *Document review*. En la etapa de plan o en la de funcionalidad, un rol así se conserva y no participa en ninguna ronda: no hay puerta de plan para un trabajo que no es programación, y una revisión de funcionalidad lee código. La página lo dice en el propio rol.\n\n**La página, control por control.** Cuatro pestañas — **Plan review**, **Code review**, **Document review** y **Feature review** —, una por clase de ronda, y cada rol está en aquella donde lo ponen su etapa y su clase. Un rol se abre en su **Name**, un selector **Stage** (Plan review, Code review o Feature review), **A programming task** y **Active**. *Active* es el interruptor del propio catálogo, compartido por todos los lados; la casilla en el encabezado del rol en *Prompts per round* es el otro, y un rol necesita los dos para ejecutarse. Debajo, cada prompt es una fila de tres: lo que muestra el selector, la ayuda emergente del selector y el texto. En un prompt de fábrica los dos primeros son fijos y **Restore** vuelve a quitar su texto; en un prompt propio los tres son suyos y **Remove** lo quita. **Add a prompt** añade uno a ese rol, y **Remove this role** — ofrecido solo en un rol propio — quita el rol.\n\n**Quitar un rol pregunta primero** y se lleva consigo los prompts que usted escribió en él: la fila se puede volver a teclear, los párrafos de debajo no.\n\n**Un borrado del que el servidor aún no se ha enterado aparece arriba de la página**, con el motivo, y sus prompts se conservan hasta que el servidor lo tenga. Se ofrece **Reload Window** cuando el motivo es que el espejo de ajustes de esta ventana se ha retirado: una compilación más nueva es dueña del archivo de ajustes, y recargar es cómo esta ventana pasa a ser esa compilación. **Finish the deletion anyway** borra los prompts ya, y dice lo que cuesta antes de que lo pulse: el servidor puede seguir ejecutando el rol sin su texto hasta que sus ajustes se pongan al día, y las rondas contra él se quejarán cada vez.",
    whatCanGoWrong: "**Un `coai-mcp` anterior a 0.19.0 no lee sus roles en absoluto.** Es la versión que aprendió a hacerlo: por debajo, los roles están en el panel y en ninguna ronda — nada falla y nada lo dice, por lo que la página muestra un aviso con la versión que usted tiene. Actualice el servidor en la pestaña **MCP server** de Settings.\n\n**Un Team server ejecuta los roles que configuró su operador.** Trae los mismos cinco y su operador puede añadir más: `Coai:ExtraRoles` en el servidor, o `Coai:AllowAnyRole` para aceptar cualquier identificador de rol VÁLIDO, lo haya nombrado quien lo haya nombrado. El panel pregunta a cada servidor configurado qué roles ejecuta y lo dice junto al rol, ANTES de una ronda en lugar de en su resultado: *work runs Architecture, Conventions — not Requirements we wrote*. Un servidor demasiado antiguo para que se le pregunte, o uno al que no se pudo llegar, sigue ejecutando los cinco de fábrica; y la frase dice cuál de los dos casos ocurrió, porque uno se arregla actualizando un servidor y el otro mirando la red.\n\n**Dos lados, dos conjuntos de roles.** Con *This side* activado, sus roles pertenecen al lado en el que trabaja, como las rondas y los umbrales. Los archivos de prompt no: una pregunta que usted escribió es una pregunta, la haga donde la haga.",
  },
  "chat-with-other-ai": {
    title: "Chat with other AI: preguntar a un segundo modelo sobre un pasaje",
    whatItIs: "Seleccione un párrafo en la respuesta de su asistente y pulse `Ctrl+Alt+A`: se abre una pestaña donde el modelo de otro proveedor lo explica en su idioma, y la conversación puede continuar. En el menú contextual lo mismo está como dos entradas, y cada una dice lo que hará: **CoAI: default** pregunta de inmediato al modelo marcado como main, y **CoAI: choose** deja el turno en el campo de texto — puede cambiar el modelo o el prompt y pulsar Enter usted mismo. Las teclas siguen obedeciendo el ajuste **Who presses send**, que una entrada de menú no puede mostrar.\n\nTambién funciona en un archivo corriente — `.md`, `.cs`, cualquiera que pueda abrir. Seleccione un fragmento y pulse las mismas teclas, o use el clic derecho. Allí la selección se lee directamente del editor en vez de copiarse por el portapapeles: es inmediato y su portapapeles queda intacto. Sin selección se envía el archivo entero, y si el archivo es grande se pregunta antes. La conversación lleva el nombre del archivo, y una segunda pregunta sobre el mismo archivo continúa la misma conversación.\n\n**CoAI: take the question** es lo mismo para una pregunta que Claude Code le hace a USTED, y está en el menú contextual del panel de Claude Code — no en el de un editor, donde no hay ninguna pregunta que tomar. Su cuadro de preguntas no se puede seleccionar, no hay nada que copiar: la pregunta se lee del archivo de sesión, con cada opción y cada descripción, y va al campo de texto. Se niega en vez de adivinar: si la última pregunta ya fue respondida lo dice, y si dos sesiones de esta carpeta están esperando lo nombra en lugar de elegir una.",
    why: "Una respuesta densa en inglés no siempre es clara, y pedirle una explicación al mismo modelo devuelve las mismas palabras. Otro proveedor la lee sin prejuicios. A mano son cinco pasos — seleccionar, copiar, pasar al navegador, chat nuevo, pegar — varias veces por hora; aquí es una tecla, y la respuesta se queda en el editor.",
    setup: "Nada, si ya hay un revisor activo en el runtime `antigravity`: ese es el que responde en un chat, y se usa el primero que puede salvo que nombre otro. Cuatro ajustes son suyos, los cuatro en la pestaña **Chat other AIs** de Settings: el prompt con el que viaja el pasaje (por defecto la palabra `Explain`), el idioma de la respuesta (inglés por defecto, y deliberadamente no el de estas páginas), con qué modelo ABRE una pestaña nueva y si se envía de inmediato. El modelo ya no es solo un ajuste: la pestaña tiene su propio selector, y lo que elija allí pertenece a esa conversación y no a todas las futuras. En esa pestaña se llaman **What to ask about the selection**, **Answer in**, **Which model answers** y **Who presses send**. **CoAI: add the question**, en el mismo menú contextual que *take the question*, es el mismo lector con el otro verbo: añade la pregunta a lo que ya hay en el campo de escritura en lugar de sustituirlo, así el turno que acaba de componer conserva su instrucción y gana la pregunta debajo como más material.\n\n**Edit chat presets** abre una pestaña con ambas listas, y todo allí se guarda mientras escribe. Desde que existen los presets, aquel prompt único son **sus prompts guardados, cada uno con un nombre** — uno marcado como el principal, que es el que viaja cuando una captura se envía sola. Al lado están **sus modelos guardados, cada uno con un nombre** y, si quiere, un prompt con el que abrir el cuadro. Lo que hubiera escrito en el antiguo prompt único se convirtió en su primer preset con nombre la primera vez que esta versión lo leyó, así que nada se perdió.\n\n**En Settings → Chat other AIs, *What to ask about the selection* es un selector.** Nombra sus prompts guardados en lugar de guardar una copia de uno, y **Edit presets…** al lado abre la pestaña donde se editan las palabras mismas: ya no hay dónde puedan discrepar. Lo que un chat recuerda es con cuál de sus prompts guardados se abre, y vacío significa el marcado como principal. *Which model answers* hace las mismas dos preguntas que la pestaña: primero el proveedor y luego uno de sus modelos — y un segundo campo vacío significa el modelo al que está configurada la propia fila del revisor.",
    usage: "La combinación de teclas copia la selección por usted y después hace lo que diga su ajuste **Who presses send**: preguntar enseguida, o dejar el turno en el campo de escritura. Los dos elementos del menú contextual no lo consultan — cada uno dice en su propio nombre lo que hará. Copiar por usted el menú tampoco puede: cerrar ese menú saca la selección del panel, así que toma lo último copiado. Por eso el pasaje se muestra arriba de la pestaña: se ve qué va a preguntarse. Una pestaña por sesión del asistente, para que dos conversaciones nunca se mezclen.\n\n**El cuadro de escritura se queda donde está** y la conversación se desplaza por encima. Solo se salta a una respuesta nueva si usted ya estaba abajo: si sube a leer algo, nada le arrastra, y **Jump to newest ↓** le devuelve cuando quiera. El cuadro crece mientras escribe hasta cerca de un tercio de la ventana, y solo entonces se desplaza. Enter envía, Shift+Enter es una línea nueva, y hay un botón **Send** para quien prefiera pulsar. A su lado, **✕ vacía el cuadro** de una pulsación, y cada control ± de arriba lleva ahora su icono — una lupa para el tamaño del texto, un sol para su tono — para que cuatro botones idénticos seguidos dejen de ser un orden que haya que recordar.\n\n**Las respuestas se componen, no se vuelcan**: títulos, listas numeradas y con viñetas, tablas, código. Los enlaces son azules, y lo que abren está acotado: una ruta DENTRO de este espacio de trabajo abre ese archivo en el editor, una dirección `http` o `https` abre el navegador, y todo lo demás se queda en texto: una ruta que sale del espacio de trabajo, una URL `file://` y una dirección que el modelo solo mencionó en una frase en vez de escribirla como enlace. Un archivo que no se encuentra lo dice, en vez de no hacer nada. Sus propias palabras van a la derecha, cada respuesta lleva el nombre del modelo que la dio, en el color de ese modelo, y una línea la cierra, de modo que el final de una respuesta larga se encuentra. **Copy answer** le da la respuesta entera como Markdown, y **Copy block** — debajo de cada bloque de código y cada cita — le da solo ese bloque. Si un modelo termina con una respuesta que le propone enviar, y la abre como un bloque ```reply, el control de ese bloque dice **Copy the reply prompt**. La extensión reconoce únicamente esa etiqueta: lo que hace que un modelo la escriba es su propio prompt, nunca algo añadido a sus espaldas.\n\n**El selector pide primero el proveedor y luego uno de sus modelos**, porque una lista de modelos pertenece a un proveedor. Cambiar a mitad de la conversación está previsto — el hilo entero viaja con usted — y junto al selector está lo que esta conversación lleva costado. Sobre el cuadro hay dos filas de presets: sus modelos en el color de su proveedor, el mismo que ese proveedor lleva en todo lo demás aquí, y sus prompts en un color que ningún proveedor tiene, para que un prompt nunca pueda confundirse con un proveedor. **Un botón está encendido solo mientras sus palabras son la instrucción vigente.** Elija un modelo a mano en las dos listas, o borre la instrucción del cuadro, y el botón que la puso se apaga; el rol que añade un preajuste de modelo cuenta igual, por eso vaciar el cuadro apaga los dos.\n\n**Un cuadro vacío con otro modelo elegido es volver a preguntar**: la misma pregunta va al otro modelo llevándose la conversación menos la respuesta que no quiso, y el botón dice de quién es el turno antes de que pulse. **Pegue una captura de pantalla** en el cuadro y viajará con la siguiente pregunta. **Stop** aparece mientras corre un turno y termina el turno para el que fue dibujado, nunca el siguiente.\n\n**Puede seguir preguntando mientras corre una respuesta.** Una pregunta enviada entonces espera su turno en una lista atenuada bajo *Thinking…*, la más antigua primero, y todavía no forma parte de la transcripción: cada fila tiene un ✕ — **Take this question back** — que retira esa pregunta y deja las demás donde están. Una imagen que pegó espera sobre el cuadro con un botón **Remove** hasta que la siguiente pregunta la lleve. Una pregunta larga suya — más de cinco líneas o más de cuatrocientos caracteres — se pliega a su comienzo para que las respuestas sigan en pantalla: **Show all … lines** (o characters) la abre y **Collapse** la vuelve a plegar. Solo se pliegan sus propias palabras, nunca una respuesta.\n\n**Un turno que falló dice por qué, en un recuadro rojo, con Try again al lado** — ofrecido solo mientras la conversación siga terminando en la pregunta que falló, de modo que nunca pueda volver a preguntar la equivocada. Y a un modelo que no guarda conversación propia hay que enviarle el hilo entero con cada seguimiento, así que una conversación así se detiene a los tres turnos: el cuadro de escritura se sustituye por **Start a new conversation** y **Continue with a local model**.\n\n**Asked** está arriba a la derecha, junto a los controles ±, y muestra lo que USTED escribió en la sesión de Claude Code de la que salió esta pestaña. Al cabo de unas horas la pregunta con la que empezó el trabajo se ha ido hacia arriba y la ventana ya no sabe decir de qué trata — y uno acaba preguntándole al asistente en qué está trabajando. Las palabras nunca se fueron: esto las lee del archivo de sesión, emparejado con esta pestaña por su propio título para que dos sesiones en una carpeta no se confundan nunca, y las fija encima de la conversación, donde el desplazamiento no las alcanza. `‹` y `›` recorren cada uno de sus turnos, del más antiguo al más reciente. Púlselo otra vez y se pliega, en medio segundo y no de golpe. Una pestaña abierta desde un archivo no tiene sesión detrás, así que no tiene botón.\n\n**Carry nothing above** está en la última respuesta. Al pulsarlo se dibuja debajo una línea naranja de trazo y punto: a partir de ahí, un modelo al que cambie y un servidor de equipo — al que se le entrega la conversación entera en CADA turno — reciben solo lo que está por debajo de la línea. No se borra nada: la conversación se queda entera donde está y puede desplazarla y copiarla como antes.\n\nNo es «olvida esto», es «no lleves esto más allá»: el modelo local con el que habla guarda la conversación en su propio proceso y conserva cada palabra. Lo que ahorra es lo otro — un cambio de modelo que si no lanzaría diez turnos sobre un tema a un modelo al que pregunta por otro, y un servidor de equipo que le cobraría esos diez turnos bajo cada pregunta siguiente.\n\nPúlselo de nuevo más abajo y el punto se traslada allí. No hay nada que deshacer: la marca es una posición, no un estado, y solo se dibuja la vigente. Sobrevive a recargar la ventana junto con la conversación.\n\n**CoAI: switch conversations…** es la lista de todas ellas. `Ctrl+Shift+Alt+G` (`Cmd+Shift+Alt+G` en un Mac), el menú contextual o la paleta de comandos. Arriba **Open**: lo que esta ventana tiene ahora mismo en una pestaña, con el modelo, cuántos turnos lleva y lo último que se dijo en ella; debajo **Recent**: todo lo demás, lo más reciente primero. Escribir filtra por el título, por el modelo que respondió y por esa última línea, así que una conversación que recuerda por una palabra de su respuesta está a una palabra. Elegir una abierta trae su pestaña al frente. Elegir una cerrada la abre de nuevo donde se quedó: la conversación entera, sin nada en marcha hasta que pregunte, y esa primera pregunta lleva la conversación al modelo que la responda.\n\n**Una papelera en cada fila cerrada** olvida esa conversación, y `Alt+Supr` (`Cmd+Supr` en un Mac) olvida la conversación bajo el cursor. La lista sigue abierta en ambos casos, así que limpiar cinco son cinco pulsaciones y no cinco aperturas de la lista. Una conversación abierta no tiene papelera: cierre antes su pestaña. **El globo del título** ensancha la lista de esta carpeta a todas las carpetas y vuelve, y el título siempre dice cuál de las dos está viendo.\n\n**Olvidar no es destruir.** La fila desaparece de inmediato y ninguna lista vuelve a mostrarla, pero la transcripción se aparta en el disco y solo se borra de verdad tras los mismos noventa días que todo lo demás: una tecla pulsada sobre la fila equivocada no le cuesta una conversación.\n\n**CoAI: go to conversation** es el camino inverso, y normalmente el que se quiere. `Ctrl+Alt+G` (`Cmd+Alt+G` en un Mac), el menú contextual o la paleta: se pulsa en la pestaña en la que está trabajando, no en una lista. Si esta ventana ya tiene esa conversación abierta, pasa al frente. Si solo está guardada, se abre de nuevo y queda ligada a esa pestaña, de modo que cada pulsación posterior llega al mismo sitio. Si no hay nada guardado para la pestaña, la lista se abre con **New conversation for it** bajo el cursor, y no se crea nada hasta que la pulse, porque un atajo es fácil de pulsar sin querer. Al pulsarla se abre el **Chat with other AI** de siempre para esa pestaña, a partir de lo que tenga seleccionado en ella. Y desde un terminal, el panel Output o cualquier sitio donde una conversación no pueda pertenecer, se abre la lista completa en lugar de no hacer nada.\n\n**CoAI: back to where this chat came from** es el camino de vuelta. Haga clic derecho dentro de una conversación, o pulse el mismo `Ctrl+Alt+G` (`Cmd+Alt+G`) mientras la conversación es la pestaña activa, y la pestaña de Claude Code o el editor desde el que se abrió pasa al frente. Tras recargar la ventana esa pestaña es otra, así que abre en su lugar la sesión de Claude Code que la conversación registró, o su archivo. Una conversación que no registró ninguna de las dos lo dice, en vez de adivinar por un nombre.\n\n**New chat**, en la cabecera de la pestaña, vuelve a empezar en la misma pestaña. La conversación en la que estaba se archiva — está entera en **CoAI: switch conversations…** con el mismo nombre — y la pestaña vuelve a ser suya, vacía, y la cita con la que empezó la anterior queda retirada. El modelo, el prompt y el nombre de la pestaña se quedan como estaban, y la siguiente pregunta llega a un modelo que no ha oído nada de ello. De eso se trata: una conversación larga sobre un asunto es un modelo que sigue cargando con él cuando usted pregunta por otro, y en un servidor de equipo es además la conversación entera reenviada y facturada con cada pregunta. Si hay un turno en marcha, primero se termina y se espera, de modo que la respuesta que estaba esperando se queda en la conversación archivada. El botón del aviso «esta conversación está llena» es el mismo.\n\n**Donde no puede estar seguro, pregunta.** Dos sesiones de Claude con el mismo nombre, o una conversación sobre este archivo guardada en otra carpeta de la misma ventana, abren la lista reducida a ellas, con un título que dice por qué, y con el nombre de la propia pestaña ya escrito en el buscador, de modo que lo que busca suele estar arriba. Un retroceso muestra otra vez todo. **Y si exactamente una conversación guardada se abrió desde una pestaña de ese nombre — y ahora hay exactamente una pestaña abierta con él —, abre esa en lugar de preguntar**: donde tiene una respuesta la usa, y donde solo tiene una conjetura, le enseña la conjetura.",
    whatCanGoWrong: "Copiar la selección requiere una sesión de Windows: la de esta máquina o — desde una ventana WSL — aquella a la que esa ventana está conectada. En los demás casos la tecla lo dice y le remite al menú, que funciona en todas partes. Si no se puede alcanzar al ayudante, o arranca y no termina, el mensaje lo nombra en vez de culpar a su selección. Si el proceso del modelo muere, la respuesta siguiente avisa de que la conversación volvió a empezar, porque de verdad no recuerda los turnos anteriores. Un revisor en otro runtime se rechaza por su nombre, en lugar de faltar en silencio: por ahora el chat habla un solo protocolo. Recargar la ventana conserva lo DICHO: cada pestaña de chat abierta vuelve con sus preguntas y respuestas, y una línea que dice que la recarga cerró la conversación. El modelo detrás ya no está — nada corre hasta que vuelva a preguntar, y esa primera pregunta lleva la transcripción a una sesión nueva: eso es lo que cuesta — o, si ha marcado la conversación, solo lo que está por debajo de la marca.\n\n**Una imagen se rechaza POR SU NOMBRE en vez de enviarse al vacío.** `codex` se rechaza como NO PROBADO, no como incapaz: su cuenta llegó a un límite de uso a mitad de la medición, y eso es una frase distinta de un no medido. Un revisor en un servidor Team todavía no tiene sitio para una imagen en el cable. Un SVG se rechaza aunque sea una imagen: es marcado con script dentro, y lo que se hace aquí es entregar un archivo a un proceso que va a abrirlo.\n\n**El total en curso lleva tilde de aproximación en dos proveedores de tres.** Solo `claude` informa de lo que cobró; en los demás la cifra se deduce de los tokens, y un turno estimado hace que todo el total sea una estimación. El registro exacto, turno a turno, está en la pestaña **Conversations** de **Show review rounds**. Y sube: una pregunta a un servidor de equipo lleva consigo la conversación entera, así que un hilo largo allí es más lento y más caro que uno corto. El remedio es **Carry nothing above**, sin perder el hilo — o capturar un pasaje nuevo.\n\n**Una conversación que la lista ofrece puede haber desaparecido ya.** La lista se construye en segundo plano y se mantiene en memoria — para que se abra al instante en lugar de leer miles de archivos mientras usted espera —, de modo que otra ventana puede olvidar una conversación entre el momento en que la lista se dibuja y el momento en que usted la pulsa. Entonces se lo dice y retira la fila, en vez de abrir una pestaña sobre nada. Una conversación que SÍ está y no se puede leer es otra frase distinta y conserva su fila: una carpeta que no respondió, o un registro escrito por una versión más nueva de esta extensión, no han perdido nada y volverán a abrirse cuando puedan.\n\n**Una conversación abierta en otra ventana de VS Code aparece en la lista, pero no puede abrirse aquí.** Su fila lo dice, y al pulsarla se le indica dónde está. Una ventana no puede traer otra al frente, y una segunda pestaña sobre una misma conversación le daría dos escritores que se sobrescriben entre sí, y acabaría partida en dos. Cambie a esa ventana. Por la misma razón no puede olvidarse desde aquí: la pestaña que la tiene volvería a escribirla.",
  },
  "the-question-consultant": {
    title: "El question consultant: otros modelos responden antes de que le pregunten a usted",
    whatItIs: "Antes de hacerle una pregunta a USTED, una IA puede hacérsela al question consultant — la herramienta `ask_consultants`. Cada fila que encendió en la pestaña **Question consultant** de Settings responde a la vez: una fila es un modelo con exactamente un prompt base — estudiar los otros proyectos de este disco, buscar en internet o dar la opinión del mejor desarrollador —, y cada respuesta vuelve a la IA por separado, marcada como consejo. Mientras los modelos trabajan, y mientras la pregunta espera por usted, aparece en la barra lateral bajo **Active questions**; cada pregunta hecha es una fila de la pestaña **Questions** de **Show review rounds**.",
    why: "Una IA que trabaja sola le interrumpe con preguntas que otro modelo podría haber respondido. Tres modelos con tres enfoques distintos responden la mayoría en pocos minutos, y a usted solo se le pregunta lo que no pudieron resolver. Mientras la IA construye un plan, la puerta lo convierte en regla y no en costumbre; una pregunta que podría tumbar producción le llega al instante, con los consultores trabajando en paralelo.",
    setup: "**Let an AI ask the question consultant first** es el interruptor. **Before it asks you** decide qué hace la puerta ante `ask_human` con una pregunta que se los saltó: *Require* la rechaza mientras se construye un plan — tras las primeras tandas de preguntas del plan y hasta su release a stage —, *Remind* solo lo recuerda, *Off* no dice nada. Un riesgo para producción con su motivo nunca se retiene.\n\n**Who answers** lista las filas. **Add a row** añade una apagada; elija su proveedor del mismo catálogo que ofrece *Add a reviewer* — también una fila API, como Grok a través de OpenRouter con el nombre de su clave en la bóveda —, su modelo y su **Prompt**. Como mucho seis filas pueden estar encendidas a la vez, y el mismo prompt puede estar en varias filas. Un prompt que el runtime de la fila no puede atender aparece en la lista pero desactivado, con el motivo medido: Antigravity no puede navegar la web, una fila API no lee el disco. Una fila de Codex, y Antigravity en disco, **can read this machine** — ningún flag las limita —, así que la fila lo dice y su interruptor espera la casilla **I accept that this row can read this machine**.\n\n**Base prompts** muestra los tres prompts incluidos y los suyos, cada uno con la capacidad que necesita. Edite uno incluido en su caja — **Restore default** devuelve el texto original — o cree el suyo con **Add a prompt…**. **Folders a disk row may read** son los únicos lugares que lee una fila de disco, solo lectura: la raíz de una unidad, su propia carpeta de perfil, una carpeta del sistema o la carpeta de datos se rechazan. **Minutes one row may run**, **Questions per session** y **Question batches that reach you first** son los límites.",
    usage: "No tiene que pulsar nada. La IA llama a `ask_consultants` con su pregunta y lo que ya intentó; **Active questions** en la barra lateral muestra la pregunta con una línea por modelo — *consulting*, luego *answered*, *timed out* o *failed*, con lo que tardó —, y la línea avanza a medida que cada modelo termina.\n\nSi después la IA le pregunta a usted, la misma pregunta se convierte en una tarjeta de **Active questions** con todas las respuestas plegadas debajo, la consulta que la precedió nombrada y un riesgo para producción marcado con su motivo. **Answer…** abre primero una caja para sus propias palabras y después las opciones habituales. Una tarjeta que nadie responde en quince minutos caduca: a la IA se le dice que pregunte en el chat y la tarjeta sale de la barra lateral.\n\nLa pestaña **Questions** de **Show review rounds** guarda una fila por pregunta — cuándo, dónde, cuántos modelos respondieron, qué costó, cuánto tardó y qué pasó después — y se despliega en una fila por modelo con su prompt, su estado y su consejo.",
    whatCanGoWrong: "**La respuesta de una fila que puede leer esta máquina lleva esa marca** en la barra lateral y en el registro, junto a la respuesta. Las filas son modelos de otros proveedores y sus respuestas son material, no instrucciones: a la IA se le indica que las verifique.\n\nUn modelo que no responde en sus minutos queda timed out y los demás responden igual. No tener a quién preguntar — ninguna fila encendida, las preguntas de la sesión agotadas, el interruptor apagado — nunca bloquea a la IA: la puerta deja pasar la pregunta y dice por qué. Un coai-mcp más antiguo no tiene question consultant en absoluto; la pestaña lo dice en un banner y no escribe ninguno de sus ajustes hasta que se actualice el servidor.",
  },
  "the-consultant": {
    title: "El consultor: un segundo proveedor para una IA atascada",
    whatItIs: "Una herramienta, `consult`, que su asistente llama ÉL MISMO cuando lleva dos vueltas alrededor del mismo fallo. Entrega el problema al modelo de otro proveedor junto con esta copia de trabajo y los cambios que aún no ha confirmado, y ese modelo lee el árbol SÓLO EN LECTURA y responde con un consejo.\n\nNada de lo que diga se aplica. La respuesta vuelve dentro de una valla y marcada como consultiva, al asistente se le dice con todas las letras que es una opinión sobre código que el consultor no puede tocar, y la corrección se sigue escribiendo y verificando aquí. Es una conversación y no una pregunta: unos pocos turnos, para que el segundo modelo pueda decir «pruebe esto y dígame qué imprimió» — y oír la respuesta.",
    why: "Dos rondas de la misma corrección equivocada es lo más caro que hace un asistente, y el modelo que produjo el punto ciego es precisamente el que no puede verlo. Otro proveedor lee el mismo árbol sin ideas previas.\n\nA mano esto significa describir el problema otra vez a una segunda IA — sin el repositorio, sin el diff y normalmente sin lo que ya se intentó —, que es por lo que la segunda respuesta es tantas veces la primera. Aquí el servidor reúne las tres partes por su cuenta: el asistente envía sólo el problema con sus propias palabras.",
    setup: "**Let an AI consult another vendor** es el interruptor, en la pestaña **Consultant** de Settings. Está encendido y no hace nada hasta que un asistente pregunta.\n\nDebajo, una fila por cada clase de llamante, porque a quién pregunta una IA atascada depende de qué IA se ha atascado. De fábrica: Claude Code pregunta a `codex`, Codex a `claude`, Gemini y todo lo demás a `codex` — nunca a sí mismos.\n\n**Se ofrece el mismo catálogo que en *Add a reviewer***, con los mismos nombres: `Codex (OpenAI)`, `Antigravity (Google)`, `Claude`. Una entrada que no puede mantener una conversación aparece debajo con su razón, en vez de faltar en silencio; un servidor de equipo no se ofrece en absoluto — una consulta nunca sale por uno.\n\n**Estos son los ajustes PROPIOS del consultor.** La segunda casilla es el modelo, y vacío significa el predeterminado de ese runtime; al lado, donde el runtime lo tiene, están su propio endpoint y la ruta a su CLI. Un proveedor aquí comparte solo el nombre — y por tanto su clave en el almacén — con la fila de revisor del mismo nombre, y nada más: cambie el modelo o el endpoint de un revisor y el consultor se queda donde usted lo puso, y borre ese revisor y el consultor sigue funcionando.\n\nAlgo que la pestaña dice en lugar de ocultar: un consultor en la CLI de Codex con endpoint propio — DeepSeek, OpenRouter, uno suyo — puede guardarse y **no puede ejecutarse en esta versión**. El servidor lo rechaza por su nombre, y la fila lo advierte donde usted elige. Una fila que, desde una versión anterior, sigue apuntando a un revisor de servidor de equipo dice lo mismo y deja de ofrecer ajustes que nunca podrá usar. La última entrada de la lista es **Another OpenAI-compatible endpoint**: pide un nombre y una URL base, igual que *Add a reviewer*, y el nombre es la clave con la que sus credenciales quedan en la entrada del baúl.\n\nElegir el proveedor del propio llamante está permitido, y la fila dice qué pensar de ello: solo merece la pena con un modelo más fuerte, porque el servidor ve qué proveedor pregunta y nunca su modelo.\n\n**What the consultant is asked to do** es el cuadro para las instrucciones que recibe antes del problema. Vacío es el prompt con el que viene esta compilación: la pestaña no puede mostrarle esas palabras, porque están compiladas dentro del servidor. Lo que usted escriba se guarda como sustitución de prompt del servidor y se lee en la siguiente consulta. **Restore default** quita la sustitución, y vaciar el cuadro hace lo mismo: no existe un prompt que no diga nada.",
    usage: "Usted no pulsa nada. El fragmento en su `CLAUDE.md` le dice al asistente cuándo recurrir a esto — el mismo fallo dos veces, o usted diciendo que sigue sin arreglarse — y llama la herramienta solo.\n\nTres números lo acotan. **Turns per consultation** es cuántas veces puede preguntarse una consulta, cinco por defecto, y al consultor se le DICE en cada turno cuántos quedan, para que el último responda en vez de hacer una aclaración más. **Calls per session** es cuántas llamadas de tipo stuck puede hacer una sesión del asistente en 24 horas — la primera pregunta y cada seguimiento por igual —, diez por defecto. **Close an idle consultation after, minutes** cierra el hilo que nadie retomó — se comprueba cada minuto mientras el servidor funciona; una pregunta posterior es entonces una consulta nueva con todo el presupuesto.\n\n**Mientras una consulta está en curso se ve en la barra lateral**, en **Active consultations**, la sección que está debajo de **Active gates**: quién pregunta a quién, por qué turno va y el aviso sobre el árbol de trabajo si saltó. Cuando termina, desaparece — la barra lateral es presente — y cada consulta que ha habido es una fila en **Show review rounds**, pestaña *Consultations*: en qué estaba atascado, qué se aconsejó y cuánto costó.\n\nNo puede haber ping-pong: una pregunta ya hecha en esta consulta se rechaza, en el turno que fuera, así que el siguiente turno sólo ocurre después de que su asistente haya probado algo de verdad y tenga qué contar. Lo que costó cada una está en **Show review rounds**, junto a las rondas de revisión y los chats.\n\n**Consultation cadence** llama a un consultor aunque nadie esté atascado. Una vez que el plan se divide en epics, cada grupo de epics debe una consulta antes de su primera ronda de código — ¿está bien este grupo, dónde flojea, qué ha olvidado? —, y la orden que lo dice, con la llamada a `consult` ya escrita, va en cada respuesta de revisión hasta que se atiende. **One consultation per this many epics** es tres por defecto. A partir de **Ask for the riskiest pieces from this many epics** — cinco — también se le pregunta al asistente qué epics e historias entrañan más riesgo, y cada uno que nombre, hasta **Riskiest pieces per plan, at most**, recibe su propia consulta. *Remind* da las órdenes y no rechaza nada; *Require* rechaza la primera ronda de código de un grupo hasta que su consulta se haya cerrado con un resultado; *Off* no da órdenes. Un consultor que no se puede alcanzar nunca atasca el trabajo: la ronda sigue adelante con el motivo escrito en ella. **Cada consulta tiene un tipo (kind)** — en su tarjeta de la barra lateral, en el registro del servidor y en la columna **Kind** de *Consultations* en **Show review rounds**: **stuck** — el asistente preguntó por su cuenta porque estaba atascado; **cadence** — la ordenó el gate para un grupo de epics; **risk** — para una pieza que el asistente señaló como arriesgada. En una ordenada, **For** dice qué epics o historia y qué plan. **Turns per consultation** y el cierre por inactividad valen para todos los tipos; **Calls per session** cuenta sólo las stuck, porque las demás las ordena el gate y él mismo las acota: una consulta abierta o cerrada con resultado por grupo o pieza arriesgada, otra sólo después de una fallida o caducada sin resultado. Una consulta ordenada que se cerró por inactividad deja de contar para su grupo hasta que alguien registre cómo terminó. El interruptor **Let an AI consult another vendor** apaga los tres tipos — una cadence en *Require* retira entonces su rechazo, con el motivo escrito en la ronda.",
    whatCanGoWrong: "**El consultor no puede escribir en su repositorio, y el servidor comprueba en lugar de fiarse.** Toma una huella del árbol antes y después, y una consulta DURANTE LA CUAL el árbol haya CAMBIADO se da por fallida y se informa, en vez de responderse: la comprobación ve que algo se movió, nunca quién lo movió, así que su propia edición mientras esperaba también la activa. Nunca borra ni revierte lo que encuentra: un archivo que usted escribió mientras esperaba es suyo, y perderlo por una comprobación de seguridad sería peor que aquello para lo que existe la comprobación.\n\n**Un consejo es material, no una instrucción.** Llega dentro de una valla que dice qué proveedor lo escribió y que es sólo consultivo, de modo que un texto del repositorio dirigido a una IA no consigue que se le obedezca por el hecho de leerse en voz alta a la suya.\n\n**La conversación vive en el almacén del otro proveedor**, que es lo que hace posible una repregunta, y contiene los cambios sin confirmar de este repositorio. Ese es el precio de la función y no nos corresponde borrarlo. Apague la función y la herramienta rechaza POR SU NOMBRE, de modo que al asistente se le dice que está apagada en vez de dejarlo adivinando.",
  },
  "install-the-server": {
    title: "Empiece aquí: instale el servidor MCP",
    whatItIs: "La extensión es la cara. Quien hace la revisión es `coai-mcp`, un programa pequeño que su asistente de IA arranca y con el que habla. Mientras no esté instalado, no revisa nadie.",
    why: "Una revisión tiene que ejecutarse donde está su código, lanzar las CLI de los proveedores y trabajar durante minutos. Una extensión de VS Code no puede hacerlo, y un servidor propiedad de una ventana de VS Code moriría con ella.",
    setup: "Abra la pestaña **MCP server** de Settings. Ahí se ve qué hay instalado, qué hay publicado, y un botón cuando difieren: púlselo. **Install the MCP server…**, en el menú ⋯ de la barra lateral de ConnectOtherAIs, es la misma instalación por la otra puerta. La descarga se verifica contra el `.sha256` de la propia release, y el binario va al almacén privado de la extensión, nunca a su `PATH`.\n\nLa instalación deja el bloque de configuración MCP en su portapapeles; **Copy the MCP config block**, en el menú ⋯ de la barra lateral de ConnectOtherAIs, lo vuelve a copiar siempre que lo necesite. Péguelo en la configuración de su asistente. Esto se hace UNA vez. Reinicie el asistente para que arranque el servidor.",
    usage: "Después volverá poco a la pestaña MCP server: la versión publicada se reconsulta como mucho cada media hora, y **Check again** pregunta ahora mismo.\n\nCada plataforma tiene su propio binario. En cada release se publican compilaciones para Windows, macOS y Linux; una máquina sin la suya lo dice con franqueza en vez de descargar la ajena.",
    whatCanGoWrong: "Si la pestaña MCP server dice que no pudo leer la versión publicada, no se alcanzó GitHub. Nada está roto: el servidor instalado sigue funcionando.\n\nSi dice *The installed coai-mcp could not report its reviewers*, al servidor se le preguntó qué revisores ejecutaría y no dio respuesta, así que ninguna tarjeta de revisor puede decir si se ejecutaría. Es un hecho sobre el binario y no sobre un revisor concreto, por eso se dice aquí y no como insignia en cada tarjeta; una actualización suele arreglarlo.\n\nSi tras pegar el bloque su asistente no muestra las herramientas, no se ha reiniciado. El bloque lleva la ruta exacta al binario; un bloque copiado de otra máquina apunta a una ruta que aquí no existe.",
  },
  "choose-reviewers": {
    title: "Después: elija quién revisa",
    whatItIs: "La pestaña **Reviewers** de Settings es el panel de modelos de otros proveedores que leerá su plan y su código. Cada fila es un proveedor: una casilla para incluirlo, un selector de modelo, un ▶ para abrir su CLI en una terminal, un ⤓ para instalar esa CLI, un ⟳ que se pone verde cuando hay publicada una versión más nueva, sus dos precios por millón de tokens — y junto a cada precio, la etapa que paga: **reviews plans** junto a la tarifa de entrada, **reviews code** junto a la de salida. Después **remove**.\n\nUna fila de servidor de equipo no tiene aquí precios donde ponerlas, porque su CLI corre en el servidor y su precio es la suscripción de la empresa: sus dos casillas de etapa van en una línea propia.\n\nDebajo, en una línea propia, están **reviews documents** y una cuarta casilla, **reviews features**: si a este proveedor se le pide revisar una FUNCIONALIDAD entera — una vez, al final de un plan de tres o más épicas, antes del lanzamiento. Está desmarcada hasta que la marque, necesita coai-mcp 0.39.0 o posterior, y una fila de servidor de equipo todavía no puede tenerla: su casilla está desactivada y dice por qué.",
    why: "Todo el sentido está en que el revisor no es el autor. Una segunda opinión del mismo modelo que escribió el código vale menos que una primera opinión de otro — y dos proveedores que coinciden en un hallazgo son la señal más fuerte que produce este producto.",
    setup: "**＋ Add a reviewer** ofrece los proveedores que conoce esta compilación: Codex, Antigravity (Gemini, Claude y GPT-OSS con una sola suscripción), un segundo Claude, DeepSeek, OpenRouter, **API (OpenAI-compatible)** — un endpoint alojado como xAI o DashScope, alcanzado directamente con una clave del baúl, sin CLI de por medio: indique la URL base y teclee el id del modelo — y una fila en blanco para cualquier endpoint compatible con OpenAI a través de la CLI de Codex.\n\nLa mayoría se autentican solos: si la CLI está conectada en esta máquina, no hace falta clave. El ▶ de una fila abre una terminal con esa CLI — ahí la conecta, y ahí su propio comando de consumo ya está escrito esperando Enter. El ⤓ abre la misma terminal con el comando de INSTALACIÓN — el oficial del proveedor, para el sistema operativo en el que esa terminal realmente se ejecuta. VS Code conectado a WSL recibe el comando de Linux, no el de PowerShell.\n\n**Un Team server es la otra forma de conseguir un revisor, y aquí no necesita nada instalado.** Una máquina en algún sitio ejecuta las CLI de los proveedores con UNA suscripción de la empresa, y todos inician sesión en ella con su cuenta de trabajo en lugar de comprar la suya. Añada uno en la pestaña **Team servers** de Settings, pulse **Sign in**, y sus proveedores aparecen en ＋ Add a reviewer con las cuentas que tienen libres. Su plan y sus diffs se envían a esa máquina, y el panel lo dice en cada fila: que sea el servidor de la propia empresa no hace menos cierto que el código sale de esta.",
    usage: "**⟳ le dice si hay algo que actualizar antes de pulsarlo.** Verde significa que el proveedor publica una versión más nueva que la de esta máquina; gris, que ya tiene la más nueva o que no se pudo leer alguno de los dos números. Ambos están en la ayuda emergente, así que el color nunca es la única señal. Al pulsarlo se abre una terminal con el comando de actualización propio de esa CLI, ya escrito y a la espera: `claude update`, `agy update` y `codex update` a partir de codex 0.126.0. La Gemini CLI, y un Codex anterior a 0.126.0 o cuya versión no se pudo leer, se instalan de nuevo con npm y `@latest`, la línea que OpenAI y Google imprimen para actualizar.\n\nDos revisores es el mínimo útil, porque la señal es la coincidencia. Tres cuestan el triple y rara vez dicen el triple.\n\nEl selector de modelo muestra a qué llega de verdad esa CLI en esta máquina: en Codex, su propia caché de modelos; en los demás, una lista curada. **another model…** acepta cualquier id exacto.\n\n**Los ajustes propios de un revisor API.** En una tarjeta *API (OpenAI-compatible)*, en cuanto coai-mcp informa de lo que acepta su modelo, aparecen tres controles más: **thinking** (solo si el proveedor documenta cómo desactivar el razonamiento; si no, la tarjeta dice que no se puede desactivar), **effort** (una lista con exactamente los niveles que acepta ese proveedor, con el calibrado marcado) y **max review time (minutes)**. Cada uno empieza en lo que la calibración fijó para ese modelo. Elegir el valor por defecto no guarda nada, así que la fila sigue a la próxima calibración; un valor que usted fije tiene su propio **reset to calibrated default**. Un ajuste que el servidor rechaza aparece en la tarjeta con el motivo del servidor. Hace falta coai-mcp 0.40.0; con uno más antiguo la tarjeta los oculta y lo dice.\n\n**El resto de una tarjeta.** Una tarjeta que ejecuta una CLI en esta máquina tiene un campo **CLI path**: vacío significa buscarla en el `PATH`, lo que es correcto casi en todas partes y erróneo en WSL, donde `codex` y `gemini` pueden resolverse a los shims de npm de Windows y morir por falta de un binario de Linux; ponga ahí la ruta nativa. Una tarjeta API no tiene CLI path, porque su CLI es el propio coai-mcp. En su lugar tiene un selector **dialect** — cómo se formula la petición para la familia de ese endpoint; `openai` es el genérico, y el propio de un proveedor solo se añade una vez medido contra el endpoint real — y un tercer campo de precio, **$ / 1M cached**, porque un proveedor que cachea un prefijo del prompt factura la entrada cacheada a una fracción de la tarifa de entrada, y el servidor calcula él mismo el precio de los turnos de esa tarjeta.",
    whatCanGoWrong: "Quitar al último revisor se rechaza: un panel sin nadie no revisa nada.\n\n**Una tarjeta que el servidor dice que no puede ejecutar lleva una insignia cannot review** junto a su nombre. Pase el puntero por encima para ver el motivo, que es lo único sobre lo que una persona puede actuar. El veredicto es cómo lee coai-mcp su archivo de ajustes en esta máquina, y la insignia lo dice: una variable en la configuración de su propio cliente MCP pesa más que ese archivo, así que el servidor en marcha puede discrepar. Una tarjeta por la que no se preguntó al servidor, o que este no mencionó, no muestra ninguna insignia: una insignia que se encendiera por una comprobación fallida sería una insignia que miente.\n\nUn proveedor cuya CLI no está instalada lo dice en **providers** antes de una ronda, no a mitad de ella. Gemini en particular está marcado RETIRED: Google cerró Code Assist para cuentas individuales y esa CLI ahora se niega antes de llegar a un modelo. Use Antigravity en su lugar.\n\nUn revisor de Team server dice qué le pasa en su propia fila: *not signed in* (pulse Sign in), *sign in again* (la sesión caducó), *outside the company domain* (volver a iniciar sesión no arregla eso), o cuántas cuentas le quedan a ese proveedor: todas con la sesión cerrada es trabajo del operador, todas limitadas vuelven solas.",
  },
  "a-local-model": {
    title: "Un modelo en su propia máquina como revisor",
    whatItIs: "Un revisor llamado **local**, respaldado por un motor que corre en esta máquina — Ollama, un vLLM, o cualquier cosa que hable la misma forma compatible con OpenAI. Su lista de modelos es lo que USTED tiene instalado, con el tamaño de parámetros, la cuantización y el tamaño en disco: lo instalado es un hecho sobre su máquina, no una lista que esta extensión pudiera traer consigo.",
    why: "No cuesta nada por ronda y nada sale del edificio. Eso lo convierte en el revisor que puede permitirse en cada push — y el único que puede usar en un cambio que no tiene permiso de enviar a ninguna parte. Es un revisor de OTRA clase que los alojados, no uno más barato: el panel existe para que los mezcle.",
    setup: "Añádalo desde **＋ Add a reviewer** y la fila se completa sola: el motor se busca en 11434 (Ollama) y 8000 (vLLM), y la lista muestra lo que tiene. Si no se encuentra nada, la fila dice dónde buscó y por qué no salió — rechazado, agotó el tiempo, respondió algo raro — en vez de mostrar una lista vacía.\n\nEl campo del endpoint es para todo lo que la búsqueda no ve: un vLLM en otro puerto, una máquina en la red, un motor detrás de un proxy. Quiere la base compatible con OpenAI, terminada en `/v1` — que **no** es la dirección que abriría en un navegador: Ollama sirve su propia API en la raíz y la compatible bajo `/v1`, y una base sin eso falla en la primera revisión con un 404 que se lee como un problema del modelo.\n\n⟳ vuelve a preguntar al motor. Una búsqueda exitosa se cachea un minuto para que el panel no liste modelos en cada repintado — así que un modelo recién descargado todavía no está ahí; ese botón es para eso.",
    usage: "**Déle sitio.** Una revisión es el prompt, el plan o el diff y el esquema, todo en una sola petición. Un modelo con una ventana de contexto pequeña rechaza en lugar de responder mal — honesto, y la ronda se gasta igual. Cuando pueda elegir, tome la variante con más contexto.\n\nEsta fila no tiene ▶ ni ⤓, y su ⟳ no es una actualización, porque esos son los botones de una CLI: aquí no hay nada en lo que iniciar sesión, nada que instalar ni actualizar. Aquí ⟳ vuelve a preguntar al motor qué tiene, y el ⇄ de al lado solo aparece en el caso de WSL descrito más abajo. Los tokens SÍ se cuentan — el motor los informa y aparecen en **What each AI has used**, dentro de **Show review rounds** — pero el dinero es un guion: un modelo en su propio hardware no tiene factura por tokens. Cuesta electricidad y una tarjeta ocupada, y este panel no ve ninguna de las dos.",
    whatCanGoWrong: "**Un endpoint que no está en esta máquina se anuncia en la fila, en rojo.** Cada revisión envía allí el prompt — su plan, sus diffs y el contenido de los archivos alrededor. Para eso sirve un motor remoto, y así es también como el código fuente sale del edificio por accidente, por eso la fila nombra el host y lo que va hacia él. Use solo uno que usted controle.\n\n**En una ventana conectada a WSL, a un motor del lado Windows le estorban DOS cosas.** Está atado a `127.0.0.1` — arránquelo con `OLLAMA_HOST=0.0.0.0`; y `127.0.0.1` de este lado es el loopback propio de WSL, no el host Windows, así que el endpoint debe apuntar a la dirección del host Windows. Cuando el motor responde desde el lado Windows y esta distribución no puede alcanzarlo, a la tarjeta le sale un ⇄ — **Switch WSL to mirrored networking** —, que es la otra salida: le muestra exactamente lo que va a escribir y luego escribe `networkingMode=mirrored` en el `.wslconfig` de Windows, tras lo cual WSL comparte las interfaces del host y `127.0.0.1` es la dirección correcta sin configurar nada más. No puede reiniciar WSL por usted — eso es `wsl --shutdown` desde Windows, y terminaría la distribución en la que corre esta extensión. El ajuste es global para todas las distribuciones, a algunos clientes VPN no les gusta, y pulsar ⇄ otra vez lo deshace.\n\n**Un modelo que el motor ya no lista** se queda en la lista marcado *NOT on this engine any more* — en vez de desaparecer (eso cambiaría su revisor en silencio) o parecer normal (eso enviaría una ronda a un modelo que responde 404).",
  },
  "teach-your-ai": {
    title: "Y: dígale a su IA que use la puerta",
    whatItIs: "El menú ⋯ de la barra lateral de ConnectOtherAIs → **Copy the CLAUDE.md snippet** da un párrafo que se pega en el repositorio que quiere revisar. Le dice a la IA que trabaja allí que existe una puerta de revisión, en qué orden se usa, y que un DOCUMENTO se revisa con una puerta propia. También dice cuándo llamar a `review_feature` — una vez, al final de un plan de 3 o más épicas, antes del lanzamiento — y que un `skipped` de la revisión de la funcionalidad no bloquea el lanzamiento.",
    why: "Un asistente con herramientas pero sin instrucción no se le ocurre abrir una sesión de revisión. Ese párrafo ES la instrucción, y vive en el repositorio y no en la extensión porque es una propiedad del proyecto, no de su editor.",
    setup: "Cópielo, péguelo en el `CLAUDE.md` de ese repositorio (o en lo que lea su asistente) y haga commit. No nombra ningún repositorio: la IA que lo lee ya está dentro de una copia de trabajo que puede nombrar ella misma.",
    usage: "A partir de ahí el asistente abre una sesión, envía el plan, resuelve los hallazgos, implementa, envía el diff y vuelve a resolver. Usted lo observa en **Active gates** y responde a lo que escale.",
    whatCanGoWrong: "Nada obliga a cumplir ese párrafo. El asistente puede ignorarlo, y la puerta no puede llamarse a sí misma. Lo que SÍ puede es negarse a revisar código mientras el plan no haya pasado, y eso lo hace.\n\n**Un fragmento pegado se queda anticuado en silencio**, porque vive en el repositorio de alguien y esta extensión sigue avanzando. La pestaña **MCP server** de Settings lee el fragmento de este espacio de trabajo y lo dice cuando le falta una parte o va por detrás en una, cuando es anterior al versionado, o cuando es MÁS NUEVO que esta compilación: alguien actualizó el repositorio desde una extensión más nueva, y entonces es esta compilación la que necesita actualizarse. En los dos primeros casos, cópielo de nuevo y sustituya el bloque antiguo: lo que cambió es lo que se le dice que haga a la IA que lo lee.",
  },
  "the-gate": {
    title: "La puerta: rondas, el umbral y qué pasa cuando se agotan",
    whatItIs: "Tres ajustes que deciden cuándo termina una revisión. **Rounds**, en el recuadro de cada rol, es cuántos intentos tiene ese ROL. **Passes at or under**, a su lado, es cuántos hallazgos bloqueantes de ese rol son aceptables. **When the rounds run out**, en la pestaña **The gate** de Settings, es qué pasa si nunca llega ahí.",
    why: "Sin límite, un bucle de revisión no termina nunca: siempre hay un hallazgo más. El umbral dice con un número qué es «suficiente» antes de que empiece la discusión.",
    setup: "CADA rol tiene sus propias rondas y su propio umbral, que se ajustan junto a los prompts de ese rol en Settings → Prompts per round: la arquitectura puede merecer dos pasadas con lentes distintas y el rendimiento una, y un presupuesto compartido hace que el rol más barato pague por el más caro. Cada rol de código tiene además una **casilla en su propio encabezado**: sin marcar, el rol no participa en la ronda en absoluto — no se lanza ningún revisor para él, nada de lo que habría encontrado cuenta, y no le presta a la etapa ni sus rondas ni su umbral. Sus números y sus prompts elegidos se conservan y vuelven sin cambios cuando la marque de nuevo. La última no puede desmarcarse: una ronda sin ningún revisor nunca se resuelve. La revisión del plan tiene un rol y no tiene casilla. **Deal the lenses across vendors** es el otro interruptor que hay ahí, en la etapa de plan: apagado, cada proveedor responde la misma pregunta y la coincidencia de dos proveedores en un hallazgo es un hecho que la puerta puede usar; encendido, cada lente se pregunta una vez, con la mitad de lanzamientos, y esa coincidencia desaparece. Su gemelo en la etapa de código es **Deal the roles across vendors**: encendido, cada rol de código se le pregunta a un proveedor en lugar de a todos, al mismo precio en coincidencia. Por omisión: una ronda para cada rol — dos para la revisión de la funcionalidad, cuya segunda ronda solo corre tras un fallo de revisor, un hallazgo bloqueante o que usted la pida —, un umbral de seis para el plan y de cinco para cada rol de código, de documento y de funcionalidad, reparto apagado y *Ask a human*. Al umbral solo cuentan los hallazgos **blocking** y **major**; minor y nit nunca bloquean.\n\nUn hallazgo levantado por dos proveedores cuenta UNA vez. Un hallazgo que usted rechazó con motivo no vuelve a contar hasta que un revisor lo levante con un argumento realmente nuevo.",
    usage: "*Ask a human* es la opción honesta por omisión: la puerta se detiene y pone la decisión delante de usted. *Continue, and say so* sigue y dice en voz alta que quedan hallazgos — y no toca ninguno, que es exactamente cómo una puerta se vuelve decoración. *Good enough — take what’s true and move on* es la intermedia: la IA lee los hallazgos abiertos, aplica los que son verdaderos y útiles, rechaza el resto con motivos y sigue. *Climb the ladder* escala — más esfuerzo del revisor, luego un modelo revisor más fuerte, luego un árbitro más fuerte — y da a la etapa un juego nuevo de rondas cada vez.\n\nTres casillas bajo ese campo no cambian lo que el gate DECIDE: son órdenes que devuelve a la IA que lo llamó, y están apagadas hasta que usted las encienda. **Work autonomously**: a la IA se le dice qué SIGNIFICA autónomo, no sólo que lo sea — cada error recibe una prueba red-green-red; la documentación, el README, el manifiesto y los documentos de módulo se actualizan con cada cambio; TODAS las pruebas se ejecutan antes de una release; donde el repositorio tenga un proceso de release o pull request, se sigue, y los comentarios automáticos de un pull request se leen cinco minutos después y se corrigen; un despliegue automático se verifica contra dev, stage o test y se leen sus logs; el código se relee contra las reglas del repositorio; y la IA dice que trabaja de forma autónoma y qué está escribiendo. Las preguntas que no bloquean se acumulan y se hacen al final, todas juntas; una que sí bloquea se hace de inmediato, pero sólo después de reunir todas las demás bloqueantes, para interrumpirle una sola vez. **Split the plan into epics and stories**: tras aprobarse un plan, se dice a la IA qué tamaño tiene — sólo historias (3-5), o 2-3, 3-4 o 4-5 épicas de historias, menos si el trabajo es menor y nunca más — y cada cuánto volver a la puerta: una vez por ÉPICA (cada épica en su rama sobre la anterior, una ronda de plan, una ronda de código sobre todo su diff, un commit) o una vez para la TAREA entera (una ronda de código al final, y aun así un commit por épica), elegido bajo el interruptor. Nunca por historia. La puerta mide el plan que usted envió y dice si necesita épicas, historias o nada, y dice en voz alta que esto es una heurística. La orden se da una sola vez por asistente: cada épica vuelve para su propia revisión de plan y se le dice que es una PIEZA — constrúyela como una sola unidad y ciérrala bien — en lugar de ordenarle dividir otra vez, lo que no tendría fin. **Split with the strongest model**: la división y las historias caras (pagos, seguridad, arquitectura) van al modelo más fuerte del asistente que llamó, y las ordinarias a su modelo de implementación. Ambos se eligen por tipo de asistente justo debajo del interruptor; para Claude Code son Fable y Opus mientras no los cambie, y a un asistente sin elección se le pide usar su propio modelo más fuerte, nunca el de otro proveedor.\n\nOtro interruptor está encima de esos tres, y no es una orden: cambia quién revisa. **Stop the local reviewer when the cloud reviewers found almost nothing**: cuando todos los revisores en la nube han respondido y encontraron como mucho una observación entre todos, el revisor local termina el lanzamiento en curso y no inicia más — la ronda indica qué no inició y por qué. Un revisor en la nube que falló lo mantiene en marcha. Una ronda lee el interruptor al empezar, así que un cambio vale desde la ronda siguiente.",
    whatCanGoWrong: "Un umbral de cero significa que bloquea cualquier hallazgo de cualquier gravedad, lo que en la práctica significa que una revisión no pasa nunca.\n\nLas rondas son por ROL: cada rol recibe su propia cuenta completa, y un hallazgo cuenta contra el umbral del rol que lo levantó, así que un rol ruidoso no puede gastarse la tolerancia de otro. Una etapa pasa cuando cada rol está en su propio número o por debajo.",
  },
  "the-gates-commands": {
    title: "Las órdenes de la puerta, con sus palabras",
    whatItIs: "**Edit commands…**, en la pestaña **The gate** de Settings, abre la página de órdenes. Muestra cada frase de la que están hechas las órdenes de la puerta — autonomía, la división, el ritmo de la puerta, la orden de modelos — y le deja escribir las suyas en su lugar. Debajo añade órdenes propias: cada una con un título, las rondas en que se da (todas, de plan o de código), un interruptor y el texto que le dice a la IA.",
    why: "Las órdenes son palabras según las que actúa una IA, y un equipo tiene las suyas: una regla de la casa, una lista de comprobación, una frase que impide a un modelo tomar atajos. Cambiar una palabra de una orden incluida era hasta ahora una versión nueva.",
    setup: "Escriba en un cuadro para sustituir un texto incluido; un cuadro vacío es el texto incluido, mostrado tenue. **Restore the shipped text** borra el suyo. Donde un cuadro tiene palabras en **negrita** delante, el servidor las mantiene escriba lo que escriba — así se reconoce que una orden se dio. Los nombres entre llaves, como `{scope}` o `{strongest}`, los rellena el servidor.",
    usage: "Sus órdenes propias se entregan a la IA después de las incluidas. Una solo se enciende cuando tiene texto, y una nueva empieza apagada. Quitar una orden quita también su texto. Todo se guarda mientras escribe, en la misma carpeta de datos que sus prompts, así que Export config lo lleva.",
    whatCanGoWrong: "Un servidor anterior a 0.33.0 ignora todo esto y da las órdenes incluidas; la página lo dice. Una orden encendida sin texto — escrita a mano en los ajustes — queda fuera de la ronda, y la respuesta nombra el archivo que escribir.",
  },
  "prompts-per-round": {
    title: "Prompts por ronda: qué pregunta hace cada ronda",
    whatItIs: "Cada rol de revisor tiene un prompt universal y cinco lentes estrechas. Esta pestaña (Settings → Prompts per round) elige qué prompt usa cada RONDA de ese rol, y está junto a las rondas y el umbral del mismo rol, porque esos tres ajustes responden juntos a una sola pregunta.\n\nLas últimas doce lentes se midieron antes de entrar aquí: tres redacciones cada una, dos ejecuciones cada una. Las tres redacciones resultaron ser tres FORMAS, y encuentran lo mismo en cantidad; se diferencian en cuánto sobrevive a una segunda ejecución: una lente escrita como tarea (*«ejecútalo dos veces, con un milisegundo de diferencia, y narra ambas»*) se repite a sí misma vez y media más a menudo que la misma pregunta en forma de lista.",
    why: "Un prompt por rol para siempre es la omisión correcta y el techo equivocado. Cuando se le pide a un modelo mirar todo, se reparte fino, y una segunda ronda de la misma pregunta amplia suele devolver las mismas respuestas amplias.",
    setup: "Un selector por ronda por rol; cada opción lleva su propósito como ayuda. Una ronda que no ha tocado muestra lo que el servidor va a ejecutar de verdad para ella — el selector nunca es una suposición ni un prompt que nadie ejecutará.\n\n**Conventions es un rol de código propio, con un solo prompt.** Juzga el diff contra las reglas que este proyecto ha escrito — `CLAUDE.md`, `AGENTS.md`, `GEMINI.md`, `.claude/rules` — y nada más, y un hallazgo ahí tiene que citar la frase que rompe. En un repositorio sin archivos de reglas sus revisores ni siquiera se lanzan, porque una pasada de convenciones sin convenciones no tiene nada que decir. Los demás roles de código dedican cada ronda a su propio tema.\n\nCada ronda sin fijar es la pregunta universal de ese rol. Una lente se pregunta cuando usted la pregunta: ya no hay rotación automática. Hubo una, no le quedaba ningún interruptor al que el panel llegara, y su único efecto restante era que este selector nombraba un prompt que el servidor no ejecutaría.\n\n**El encabezado de la etapa de código hace la cuenta en voz alta** — *2 vendors × up to 4 roles = 8 reviewers per round, each runs once per round, up to 1 round* —, contando solo los proveedores y los roles que están activados. *Up to*, porque los revisores de Conventions se omiten en un repositorio sin reglas escritas, y el panel no puede saberlo antes de que la ronda mire. Debajo, **What a reviewer gets** es el otro interruptor de la etapa de código: **Fast — diffs only** o **Full — with the code**. *Bajo el capó: dónde se ejecuta realmente un revisor* explica lo que cuesta cada uno y por qué Fast es el valor por defecto.\n\nTras la etapa de código vienen dos grupos más. **Document stage** contiene los roles que `review_document` ejecuta sobre un DOCUMENTO en lugar de un diff — ahí vienen *The document* y *Summary* —, cada uno con su propia casilla, rondas, umbral y selectores. **Feature stage** contiene el rol que `review_feature` ejecuta una vez, al final de un plan de tres o más épicas, sobre la funcionalidad entera. Su casilla es el interruptor propio de la puerta de funcionalidad: sin marcar, la puerta registra que la revisión de la funcionalidad no se ejecutó, y no bloquea. Qué proveedores revisan una funcionalidad lo decide la casilla **reviews features** de cada tarjeta de revisor.",
    usage: "**Deal the lenses across vendors**, en la etapa de plan, y **Deal the roles across vendors**, en la etapa de código, son los interruptores junto a estos selectores, y son los que cambian cómo se gasta una ronda: apagados, cada proveedor responde cada pregunta de esa ronda; encendidos, los prompts de la ronda — en la etapa de código, sus roles — se reparten entre los proveedores, de modo que cada pregunta se hace una vez en lugar de una vez por proveedor. Lo que gasta es el acuerdo: dos proveedores que presentan el mismo hallazgo son la señal más fuerte de este producto, y una ronda repartida no puede producirla. Precisamente por eso vienen apagados por omisión.\n\nCuando de verdad quiera dos lentes distintas sobre un cambio, póngalas en dos rondas y deje correr las dos. Se midió: en dos rondas de código, gastarlas en lentes distintas encontró MENOS hallazgos distintos que hacer dos veces la pregunta universal (17 contra 25), por menos dinero — por eso nada lo hace por usted.\n\nEl texto completo de cada prompt está en **The prompts, in full**.",
    whatCanGoWrong: "**Lo que la medición NO establece.** En tres planes, la unión de tres lentes encontró aproximadamente el doble que cualquiera sola — y ese resultado no sobrevive a su propio control: el MISMO prompt sobre el MISMO texto tres veces dio 6, 4 y 5 hallazgos con solapamientos de 3, 1 y cero. La varianza entre ejecuciones explica sola esa diferencia. Las lentes se ofrecen porque sirven para apuntar, no porque se haya demostrado que encuentran más.",
  },
  "limits": {
    title: "Límites: cuántos a la vez y cuánto se espera a cada uno",
    whatItIs: "**Reviewers at once** limita todo el abanico. **Per vendor** limita a un proveedor. **Reviewer timeout** es cuánto puede tardar un solo revisor. **Round limit** es cuánto tienen todos entre ellos. **Wait for you** es cuánto espera una escalada a una persona antes de rendirse.",
    why: "Una ronda de código con dos proveedores son ocho procesos que quieren arrancar en el mismo instante: los cuatro roles de código de fábrica por dos proveedores. Sin límite, es justo aquí donde llegan a la vez los límites de procesos del sistema, los ficheros de bloqueo de las propias CLI y los límites de los proveedores — y cada uno parece un timeout mientras no se le llame por su nombre.",
    setup: "Por defecto, tres a la vez y dos por proveedor. El límite por proveedor existe porque el límite de peticiones se cuenta por proveedor: un único límite global gastaría tranquilamente todas las plazas en uno solo.\n\nEl timeout del revisor es de diez minutos. Una ronda de código sobre un diff grande tarda de tres a cinco.\n\nEl límite de ronda acota una ronda entera y no a un revisor, y por defecto es 0, lo que significa que se calcula en vez de adivinarse. Una ronda pasa sus proveedores por sus roles a través del límite de arriba, así que necesita tantas oleadas como dé esa división, y cada oleada puede llevarse honradamente un timeout de revisor completo: tres proveedores, cuatro roles de código y un límite de tres son cuatro oleadas, cuarenta minutos. Ponga un número y anula ese cálculo. Ponga uno pequeño y estará cortando revisores que no han terminado: se cancelan, sus hallazgos se pierden y la ronda se decide sin ellos.",
    usage: "Suba el límite global en una máquina con núcleos libres y bájelo en el portátil en el que además está trabajando. Quien choque contra los límites del proveedor debe bajar precisamente el límite POR PROVEEDOR.",
    whatCanGoWrong: "El timeout mata todo el árbol de procesos, no solo la CLI: los hijos de un revisor no le sobreviven.\n\nQue expire **Wait for you** no es un fallo: la escalada sigue abierta en el panel, y la IA recibe la instrucción de preguntarle en la conversación.",
  },
  "language-and-translator": {
    title: "Idioma: las preguntas van en inglés",
    whatItIs: "Aquí ya no hay nada que ajustar. Una pregunta `call_human` le llega como una frase fija en inglés y tres botones, y su respuesta vuelve exactamente como la dio.",
    why: "Antes había un traductor: la pregunta era prosa que había escrito una IA, había que leerla y usted respondía con sus palabras. Tres botones quitaron todo eso. Un subproceso por escalada que puede expirar, negarse o responder en el idioma equivocado es una pieza móvil que no gana nada.",
    setup: "Nada. Los controles **Ask and answer in** y **Translated by** ya no están, junto con los ajustes `COAI_LANGUAGE` y `COAI_TRANSLATOR_*` que había detrás.",
    usage: "El idioma de ESTA ayuda es aparte y sigue siendo suyo: el selector de la parte superior de estas páginas lo cambia, y se guarda como `coai.helpLanguage`. Lo que cambió es el lado de los revisores, no el de la lectura.",
    whatCanGoWrong: "Aquí ya no puede fallar nada, que era el punto. Si escribe texto libre en un botón que lo permite, llega a la IA sin mediación — vale más que las mismas palabras pasadas a otro idioma por un tercer modelo.",
  },
  "vendor-keys": {
    title: "Claves de proveedor: solo cuando una CLI no sabe autenticarse sola",
    whatItIs: "Una única entrada de tipo `config` en CredsForDevs que guarda una clave por cada proveedor que la necesite. La pestaña **Vendor keys** de Settings muestra cuáles de sus revisores la necesitan de verdad.",
    why: "La mayoría de las CLI de revisor ya tienen sesión iniciada en su máquina y no necesitan clave alguna. Quienes sí la necesitan — un endpoint propio, DeepSeek, OpenRouter — no deberían teclearla en un fichero de ajustes.",
    setup: "Solo hace falta si la fila del revisor lo dice. Cree una entrada `config` en CredsForDevs, guarde ahí las claves como `{\"deepseek\": \"sk-…\"}` y pegue su identificador en **CredsForDevs config key**.",
    usage: "El servidor lee la entrada al arrancar y pasa cada clave a su proveedor por el entorno, nunca por la línea de comandos. Cambiar una clave surte efecto en el siguiente arranque del servidor.",
    whatCanGoWrong: "Un proveedor que necesita clave y no la tiene aparece en **providers** como `unavailable` con su motivo y se cae del abanico — no se salta en silencio.",
  },
  "team-servers": {
    title: "Team servers: revisores con la suscripción de la empresa",
    whatItIs: "La pestaña **Team servers** de Settings enumera los Team servers que conoce esta máquina, una fila por cada uno, y **＋ Add a Team server** añade otro. Una fila es el nombre y la dirección del servidor, la cuenta con la que ha iniciado sesión — o *no account* —, una frase que dice cómo están las cosas, cuántas cuentas tiene libres cada uno de sus proveedores, una línea que nombra el host al que va cada revisión enviada allí, y dos botones: **Sign in** o **Sign out**, y **Remove**.",
    why: "Un Team server ejecuta las CLI de los proveedores en una sola máquina, con una sola suscripción de la empresa, de modo que nadie necesita una suscripción propia. Todo lo que necesita saber antes de confiarle una revisión — quién es usted para él, si está en marcha, si tiene una cuenta libre y adónde va su código — es una propiedad de ese servidor y no de un revisor concreto, así que se dice una vez, aquí, en lugar de repetirse en cada tarjeta de revisor.",
    setup: "**＋ Add a Team server** pregunta dos cosas: un nombre corto, que es suyo y solo sirve para mostrarse, y su dirección. Después pulse **Sign in** e inicie sesión con su cuenta de trabajo; mientras eso ocurre, la fila dice *Signing in…* y sus botones están desactivados, para que un inicio de sesión lento no pueda confundirse con uno que no hizo nada. Una vez dentro, la fila pregunta al servidor qué ofrece, y sus proveedores aparecen en **＋ Add a reviewer**, en la pestaña Reviewers.",
    usage: "**La frase bajo la cuenta dice cómo están las cosas.** *Not signed in.* es el caso simple. *<account> is signed in on another side of this machine — press Sign in to use it here* significa, por ejemplo, una ventana de Windows y otra de WSL, y que este lado todavía no ha iniciado sesión por sí mismo. *Signed in. Asking what it offers…* pasa a ser *Signed in. Server <version>.* en cuanto el servidor ha respondido. Un problema se dice con las propias palabras del servidor, y cuando la fila muestra una respuesta anterior termina en *— showing what it last said*.\n\n**Una línea por proveedor cuenta sus cuentas**: *codex: 2 of 3 ready, 1 cooling down*; *no accounts — ask the operator*; *all 3 signed out — the operator must sign them in*; *all 3 rate-limited, they come back by themselves*. Esa es la diferencia entre una espera y una avería, antes de que una ronda la descubra por usted.\n\n**Sign out** termina su sesión en el servidor. **Remove** pregunta primero: cierra su sesión, borra el token de esta máquina y olvida el servidor, y cuando todavía hay filas de revisor que apuntan a él, las nombra y ofrece **Remove it and N reviewers** o **Remove the server only**; su historial de gasto se conserva en ambos casos.\n\nUn administrador del servidor ve una línea más: qué versión de Team server está publicada y si este la ejecuta. No hay botón de actualizar ni puede haberlo: un Team server se despliega en su propia máquina, no se descarga en esta. Lo que ha gastado un Team server está en **What each AI has used**, en un bloque propio.",
    whatCanGoWrong: "**Cada revisión enviada a un Team server sale de esta máquina**, y la fila lo dice en una frase que nombra el host: su plan, sus diffs y el contenido de los archivos que los rodean. Que sea el servidor de la propia empresa no lo hace menos cierto.\n\n**Un aviso de que el servidor habla una versión más antigua de la API** significa que esta extensión necesita un Team server más nuevo que el que responde. Es un aviso y no un rechazo — las revisiones siguen saliendo —, pero una mitad puede leer mal a la otra, y el remedio es actualizar el Team server, que es trabajo de su operador.\n\nQuitar un servidor no quita los revisores que apuntan a él salvo que usted lo elija; una fila de revisor que sigue apuntando a un servidor que ya no está solo puede fallar. Si el cierre de sesión falla, se le dice, y la eliminación sigue adelante: un archivo de token que sobrevivió a una eliminación es una credencial que nadie vigila.",
  },
  "bugz": {
    title: "Bugz: los defectos que su puerta ya encontró",
    whatItIs: "Cada hallazgo ACEPTADO es un defecto que una persona confirmó. **Bugz** los vuelve a leer como material, no como registro: encuentra el método del que trataba, encuentra el commit que lo arregló y guarda el par. **Collect** busca; **Review bugs** es donde usted decide qué conservar.",
    why: "Una puerta de revisión produce algo que casi todas las herramientas tiran: pares de código que estuvo mal y luego bien, cada uno confirmado por una persona en vez de adivinado. Medido sobre una base real el 15-09-2026 — 8 687 hallazgos se estrechan a 462 utilizables en 115 historias y 15 repositorios.\n\n**Solo se lee lo que ya está en su máquina.** Los hallazgos vienen de sus propias rondas y el código de su propio historial de git. Recolectar no envía nada a ninguna parte.",
    setup: "Elija un **modelo de clasificación** — solo se ofrecen motores que corren en esta máquina, y eso es una decisión, no cautela: el título y la descripción de un hallazgo son las palabras de los revisores sobre su código, y NO están anonimizadas. El anonimizador actúa después y solo sobre el código fuente. Así que ese paso las lee aquí o no las lee.\n\nLuego pulse **Collect**. La sección muestra la ejecución mientras ocurre y, al terminar, qué hizo con cada candidato.",
    usage: "Una ejecución decide cada hallazgo sin procesar y anota qué decidió: **collected** con el commit que lo arregló, **skipped** con un motivo, o **failed**. Skipped es lo corriente — un lenguaje que aquí nadie analiza; un commit que ninguna rama alcanza ya; un arreglo que no está en este repositorio — y el motivo se conserva, de modo que la tasa es una medición y no un encogimiento de hombros.\n\nLa ejecución se recuerda, así que cerrar la ventana o pulsar F5 cambia lo que USTED VE y nunca lo que ocurrió. Pulse Collect más tarde y tomará los que nadie ha mirado todavía.\n\n**Who holds a key** es la otra mitad: las claves de quienes contribuyen que su servidor de ingesta ha emitido, lo que cada una ha enviado y el botón que termina con una. Ejecute primero **Set the bugs admin key**: se guarda en el almacén de secretos del editor de esta máquina, nunca en la configuración, porque la configuración se sincroniza y una credencial de administración que le sigue a otra máquina es una de la que nadie responde.\n\nUna clave se muestra UNA vez, al emitirse. Si cierra la ventana antes de copiarla, la pestaña se la vuelve a ofrecer la próxima vez y puede revocarla por usted: el servidor no la mostrará una segunda vez. Revocar pregunta antes y nombra la nota de la clave y el mes en que se usó por última vez, porque los identificadores son hexadecimales y se parecen entre sí.\n\n**Send** es el último paso, y el que esta sección no podía dar en absoluto hasta ahora: sube los pares que usted conservó, por el mismo modo de una sola vez que antes se ejecutaba a mano en una terminal. Ejecute primero **Set the bugs contributor key**: una clave distinta de la de administración, guardada en el mismo sitio y por la misma razón.\n\n**Adónde van los pares** es el último botón de la sección. **Set the ingest server…** pide la dirección del servidor de ingesta de defectos; una vez fijada, el botón dice **Ingest server: <address>**, de modo que el destino está en pantalla cada vez que pulsa Send, y pulsarlo lo cambia. Una dirección vacía no envía a ninguna parte.\n\nUn par se marca como enviado solo cuando el servidor dice que lo tiene, así que un envío interrumpido no pierde nada: pulse Send otra vez y los que llegaron se reconocen en lugar de guardarse dos veces. Mientras un envío corre, el botón lo dice, y lo sigue diciendo tras recargar, porque la ejecución queda escrita donde ambas mitades la ven.\n\n**Review checkouts on this machine** es un comando de la paleta y la otra mitad del botón *Check out <sha> in a new window* de una fila. Enumera cada copia que ese botón ha hecho aquí — qué repositorio, qué commit, cuándo y si aún sirve —, abre cualquiera de ellas y permite devolver una.\n\nUna eliminación se RECHAZA, con nombres, si la copia contiene algo suyo: un archivo modificado, un archivo nunca confirmado, o cualquiera de los dos dentro de un submódulo — que un status normal ve pero nunca nombra. Los archivos ignorados son el caso que nadie espera (`.env`, una configuración local): se cuentan, se muestran algunos, y solo se van si lo pide una segunda vez.\n\n**CoAI: choose** en cada fila pone ese par en un chat — Where, Why, Fix, Complexity, Before, After y su comentario, incluido el que aún no se ha guardado — y no envía nada: el modelo y la pregunta los elige en el chat, como tras *CoAI: choose* con el clic derecho. Cada defecto tiene su propia conversación, con el nombre de su método; pulsarlo de nuevo la trae de vuelta sin tocar lo que ya había empezado a escribir allí.\n\n**Cada línea de Before y After está numerada.** Un esqueleto cuenta desde la primera línea de su método, porque solo se guardó el método; el código real cuenta como su archivo en ese commit. El número y el +, − o ~ junto a él se dibujan, no se escriben en el código, así que una copia del código lleva solo el código.",
    whatCanGoWrong: "**Una ejecución interrumpida lo dice.** Cierre la ventana a mitad y la fila deja de decir que está viva; la próxima vez que alguien pregunte, queda marcada como interrumpida en lugar de parecer que sigue. Lo que ya había decidido se conserva, porque cada candidato se escribió al decidirse.\n\n**Más de la mitad de los commits son inalcanzables, y es normal.** El squash-merge borra la rama en la que corrió una ronda — el 55,7 % de los candidatos medidos — pero los objetos sobreviven, así que el método aún se puede leer y la búsqueda aún se puede acotar con la ronda siguiente de la misma sesión.\n\n**Un modelo que no sea local se rechaza, venga de donde venga.** El panel no ofrecerá ninguno, y el recolector lo rechaza igualmente antes de leer un solo hallazgo: una lista desplegable no es una garantía.",
  },
  "review-bugs-page": {
    title: "La página Review bugs: conservar, descartar y leer el código",
    whatItIs: "**Review bugs**, en la sección Bugz de la barra lateral, abre una página con cada par que ha hecho Collect: una fila por método, plegada, con su gravedad, su categoría, su título y su decisión hasta ahora — *undecided*, *kept* o *dropped*. La línea de arriba dice cuántos esperan todavía por usted. Abierta, una fila muestra dónde estaba el hallazgo y qué dijeron los revisores, el código Before y After, los botones que abren ese código y **Your comment on this pair**.",
    why: "Un par solo se envía si una persona lo conservó, y una persona solo puede conservar lo que ha leído. Doscientos pares mostrando cada uno dos esqueletos es una página que nadie recorre, así que lo primero que muestra la página es la LISTA, y el código cuando usted lo pide — y cada forma de llegar al archivo real dice de qué revisión se trata.",
    setup: "Nada que configurar. El botón está desactivado hasta que Collect haya hecho al menos un par. **Which project** y **Which language**, sobre la lista, la reducen a uno de cada.",
    usage: "**Marque filas y decídalas juntas.** **Keep selected** y **Drop selected** deciden cada fila marcada, **Clear selection** las desmarca todas, y la casilla de la cabecera marca todas las filas. **Expand all** y **Collapse all** abren y pliegan todas las filas; un clic en la línea de una fila abre esa.\n\n**Real code** cambia el Before y el After de los esqueletos anonimizados a los métodos tal como son de verdad. Es solo una vista: lo que transmite un envío es el esqueleto, muestre esto lo que muestre.\n\n**Tres caminos al código, y cada uno dice qué código es.** **Open at <sha>** abre el archivo tal como era en el commit que leyeron los revisores, en solo lectura, directamente desde git — incluso cuando ninguna rama alcanza ya ese commit, que tras un squash-merge es lo habitual. **Open CURRENT (may differ)** abre el archivo tal como está ahora en su árbol de trabajo, que es donde se haría un arreglo y puede no ser ya el código que leyeron los revisores. **Check out <sha> in a new window** extrae el repositorio entero en ese commit a una carpeta propia; es más lento, porque es una extracción real y la primera además trae los submódulos. **Who calls this?** pregunta al soporte del lenguaje quién llama al método y a qué llama él — en la copia de trabajo ACTUAL, cosa que el botón dice antes de que lo pulse, porque la fila trata del commit que leyeron los revisores.\n\n**Your comment on this pair** viaja con él: se envía con el par al servidor del corpus, en público y sin anonimizar, exactamente como lo escribió, hasta mil caracteres. Una vez que el servidor tiene el par, el cuadro pasa a solo lectura y dice cuándo se envió.",
    whatCanGoWrong: "**Una página que no pudo leer los pares lo dice**, con el motivo del servidor, y *Nothing has been collected yet* significa otra cosa: pulse Collect. Las dos le mandan a sitios distintos, por eso nunca son la misma frase.\n\n**Un comentario es público.** Es lo único de esta página que se envía tal como lo escribió en lugar de anonimizado, y la línea bajo cada cuadro de comentario lo dice. Un comentario que el servidor no guardó después de enviarse el par se nombra en la fila, con el motivo.\n\n**Open at <sha>** no se ofrece cuando no se puede leer el commit o el archivo en él, y la fila dice por qué al lado, en lugar de ofrecer un botón que no abre nada.",
  },
  "who-holds-a-key": {
    title: "Who holds a key: las claves de contribuidor que emitió su servidor de ingesta",
    whatItIs: "**Who holds a key**, en la sección Bugz de la barra lateral, abre una página que enumera las claves de contribuidor que ha emitido su servidor de ingesta: la nota de cada clave, su id, cuándo se usó por última vez, cuántos pares ha enviado y cuántos están esperando, y **Revoke** en cada clave todavía viva. Sobre la lista: **Issue a key**, **Refresh**, y **Back** y **Next** para recorrerlas por páginas.",
    why: "Una clave de contribuidor permite a alguien enviar pares a su corpus. Una clave de la que nadie sabe dar cuenta es una puerta que nadie vigila, así que la página responde quién tiene una, qué ha enviado cada una, y termina con una de una pulsación.",
    setup: "Ejecute primero **Set the bugs admin key**. Se guarda en el almacén de secretos del editor de esta máquina, nunca en los ajustes, porque los ajustes se sincronizan y una credencial de administración que le sigue a otra máquina es una de la que nadie puede dar cuenta. Sin ella, la página lo dice y ofrece el mismo botón.",
    usage: "**Issue a key** pregunta para qué es la clave — su registro de por qué existe, *the tuesday workshop*, nunca el nombre ni la dirección de quien la tenga — y después muestra la clave UNA sola vez. **Copy the key** la pone en su portapapeles. **Discard and revoke it** es para una clave que al final no va a entregar: la revoca en el servidor, para que no quede viva ninguna clave que nadie tenga.\n\n**Revoke** pregunta primero y nombra la nota de la clave y el mes en que se usó por última vez, porque los ids son hexadecimales y se parecen entre sí.",
    whatCanGoWrong: "**Una clave emitida y nunca copiada se queda en esta página**, sobre la lista, hasta que la copie o la descarte: el servidor no la mostrará una segunda vez. Si una ventana se cerró entre que el servidor creó una clave y esta máquina se enteró, la página dice que *puede* haberse emitido una clave: no puede mostrarla, sería la fila más reciente, y revocar esa fila es cómo se asegura de que nadie tiene una clave que usted no tiene. **I have checked the list** descarta ese aviso.\n\nUna clave que no se acepta no se diagnostica: el servidor responde igual, a propósito, a una clave errónea, a una clave revocada y a un servidor sin administradores, así que la página no puede decirle cuál es — compruebe la clave que se guarda aquí y el log de arranque del servidor. Un servidor al que no se pudo llegar y uno que le está limitando lo dicen cada uno y ofrecen **Try again**; nada se reintenta solo. Una petición que el servidor rechazó ofrece **Back to the newest**, que es donde volver a empezar si estaba paginando. Un servidor de ingesta al que esta página no enviará una clave de administración se rechaza antes de enviar nada, y la página dice que la clave no fue a ninguna parte: cambie el servidor de ingesta en la sección Bugz y vuelva a abrir la página.",
  },
  "recent-rounds": {
    title: "Active gates, Active consultations y Consultation cadence: qué está en marcha ahora mismo",
    whatItIs: "Tres secciones de la barra lateral, una debajo de la otra. **Active gates** es cada ronda en curso, la más reciente arriba, completa: qué se revisa, la etapa, la rama, cuánto lleva — y debajo cada revisor que la ronda lanzó, con lo que ha hecho hasta ahora, cuántos hallazgos ha presentado, cuánto ha tardado ÉL y qué ha leído. **Active consultations** es cada consulta que se está teniendo ahora mismo. **Consultation cadence** es en qué punto está cada plan que sigue la cadencia de consultas.",
    why: "Una revisión tarda minutos, y lo que se espera no es un veredicto sino los revisores que lo producen. Una ronda terminada es otra pregunta — «qué pasó» — y eso es un registro, que pide una tabla con filtros, ordenación y búsqueda, no una barra lateral. Así que la barra lateral se queda solo con el presente.",
    setup: "Nada que configurar. El servidor escribe la ronda en disco al arrancarla y la actualiza a medida que avanzan los revisores, así que la imagen sobrevive a recargar la ventana, reiniciar la extensión y matar el servidor.",
    usage: "No hay nada que pulsar: una ronda en curso ya está abierta, y cuando termina sale de la barra lateral. Todo lo que ha corrido alguna vez — terminado, interrumpido, cada revisor y cada número — está en **Show review rounds**: el icono de lista en la barra de título de la barra lateral de ConnectOtherAIs, o la paleta de comandos, y mientras una pregunta le espera, el elemento de la barra de estado también lo abre.\n\n**En Consultation cadence, una línea por cada plan que sigue la cadencia** — `PLAN_x.md · epics closed 4/14 · consultation for epics 4-6: due` — y la rama en la que está. Dice qué grupo de épicas debe su consulta y si ya se ha atendido (*taken*), cuántas de las piezas arriesgadas se han consultado y, en *Require*, que la ronda de código la espera. Se dibuja como aviso mientras una consulta está pendiente o el registro de la cadencia no se puede leer, y como una línea normal cuando ya no queda nada por hacer.\n\n**En Active consultations, una tarjeta por cada consulta en curso**: quién pregunta a quién y con qué modelo, de qué tipo es y para qué, la rama, *asking* u *open* con el turno en que va de cuántos, cuánto hace que no pasa nada y los tokens hasta ahora. Una consulta cuyo proceso murió entre preguntar y oír la respuesta se lee *resumable*: el turno no se contó, y la IA la retoma con su id de consulta. El aviso sobre el sistema de archivos está en la tarjeta cuando saltó. Si no hay nada en marcha, la sección lo dice, y dónde están las terminadas.\n\nEse registro contiene sus CONVERSACIONES además de sus rondas, cada una en su propia pestaña — **Rounds** y **Conversations** —, porque «cuánto me ha costado hoy» rara vez es una pregunta sobre solo una de ellas. Una conversación no tiene repositorio, rama, etapa ni veredicto, así que su pestaña oculta esas columnas y sus filtros en vez de mostrarlos vacíos: un chat no está atado a una rama. *El registro: Show review rounds* recorre la página pestaña por pestaña.\n\nLa columna **Took** del registro informa de dos tramos de tiempo, no de uno: `2m 10s · 5m 0s` es cuánto corrieron los revisores y, después, cuánto llevó DECIDIR — desde que la ronda terminó hasta su última decisión. Una ronda que nadie ha decidido muestra un solo número, y una conversación también. Una llamada a `resolve` sella con un mismo instante todo lo que toca, así que en una ronda corriente la segunda cifra es la decisión; en una ronda que usted retomó después de comer, la comida cuenta.\n\n**Cada fila termina en Export, y el registro entero puede salir como un fichero.** El **Export** de una ronda escribe un CSV donde usted elija: cuándo corrió, en qué rama y repositorio, su veredicto, de cuántos hallazgos dependía, ambos tiempos, los tokens, las tres cifras de coste y una línea por revisor — y después una línea por HALLAZGO, cada una repitiendo las columnas de la ronda y su decisión sobre él, con las mismas palabras que usa la página (*took*, *declined*, *open*), y el motivo del rechazo al lado.\n\nPara más de una ronda, márquelas. La casilla de la cabecera selecciona todas las rondas que los filtros aceptan en ese momento — en todas las páginas, no solo la de la pantalla — y el botón de la barra dice cuántas ha elegido y cuántas de ellas quedan fuera de vista (*Export 41 selected (3 hidden)…*). Filtrar nunca deshace una selección; **Clear selection** la descarta de un gesto. Una exportación masiva informa de cuántas rondas ha leído y puede cancelarse — si la detiene no se escribe nada — y por encima de quinientas rondas pregunta antes.\n\n**Una ronda puede omitirse.** La revisión de la funcionalidad registra una ronda que nadie pudo atender — ningún proveedor marcado para funcionalidades, la puerta apagada, un plan de menos de tres épicas — como **skipped — did not block**: una insignia neutra, sin duración y, al abrirla, el motivo del servidor (con ×N si la misma omisión se repitió). No retuvo el lanzamiento; está ahí para que la falta de una revisión quede registrada en vez de ser invisible.",
    whatCanGoWrong: "Una ronda abandonada por un servidor caído pasa a *interrupted* en el siguiente arranque y desaparece de aquí; sigue en el registro. Si en Active gates se lee *Nothing is running* mientras su asistente dice que está revisando, el servidor con el que habla escribe en otro sitio — un `COAI_DATA_DIR` en su configuración que esta ventana no comparte.\n\nEn un fichero exportado, una medición ausente sigue ausente: una ronda cuyos tokens nadie registró deja la celda vacía en lugar de un cero, porque el cero es un número que alguien midió. Una ronda cuyos hallazgos no se pudieron LEER nunca se escribe como una ronda que no encontró nada: la columna `findings_read` lo dice para cada una — *loaded*, *not recorded* o *failed* —, las columnas de hallazgos quedan vacías en los dos últimos casos, y el mensaje posterior a la exportación nombra cada ronda que no pudo leer. Si no se pudo leer nada, no se escribe fichero y el diálogo de guardado no se abre.\n\nNada del fichero puede ejecutarse al abrirlo: una rama o un título que empiece por `=`, `+`, `-` o `@` se escribe como texto, incluso cuando se esconde tras un espacio. El instante se escribe dos veces — tal como se guardó, en UTC, y según el reloj de su máquina indicando el desfase — porque un fichero no puede saber en qué huso se leerá dentro de un año. Cancelar el diálogo de guardado no hace nada y no dice nada; una escritura que falla dice qué falló y nunca afirma haber tenido éxito. Con un `coai-mcp` anterior a esta versión, una exportación masiva sigue funcionando: una ronda cada vez, cuatro a la vez.",
  },
  "the-rounds-log": {
    title: "El registro: Show review rounds",
    whatItIs: "**Show review rounds** es la página que guarda todo lo que ya ha ocurrido. Se abre desde el icono de lista en la barra de título de la barra lateral de ConnectOtherAIs, desde la paleta de comandos y — mientras una pregunta le espera — desde el elemento de la barra de estado. Cualquier pregunta que le espere está arriba, bajo *Open questions — a review is waiting on you*, con **Answer…** en cada una. Debajo, seis pestañas: **Rounds**, **Conversations**, **Consultations**, **Questions** — cada pregunta hecha al question consultant, con sus modelos al desplegarla —, **What each AI has used** y **What it keeps missing**.",
    why: "La barra lateral está en presente a propósito: lo que alguien espera son los revisores que están corriendo. «Qué pasó» es otra pregunta — un registro, que pide filtros, ordenación, búsqueda y más de una página — y son cinco preguntas en lugar de una: qué decidió la puerta, cuánto costaron los chats, si consultar sirvió de algo, cuánto costó todo y qué sigue sin ver la IA por sí misma.",
    setup: "Nada que configurar. La página lee lo que el servidor ha registrado, y avanza sola mientras corre una ronda sin perder su ordenación, sus filtros ni su búsqueda.",
    usage: "**Rounds** se abre en el día de hoy. La barra de herramientas tiene un cuadro de búsqueda — asunto, rama, repositorio, revisores, modelos —, **From** y **To**, que admiten una hora además de un día, **Today**, **All dates** para quitar el intervalo, un filtro para cada uno de repositorio, rama, etapa, estado, veredicto y proveedor, y **Clear**, que quita de una vez la búsqueda, las fechas y todos los filtros. **Export selected…** y **Clear selection** son para las filas que marque. Se muestran doscientas filas cada vez, y **◀ Newer** y **Older ▶** cambian de página. Pulse una columna para ordenar, una fila para ver sus revisores.\n\n**Conversations** es la misma tabla para sus chats: su columna **Round** es **Turn** y su columna **Reviewers** es **Who answered**, y aquello para lo que una conversación no tiene respuesta — repositorio, rama, etapa, veredicto, hallazgos, las casillas y la exportación — se oculta en vez de mostrarse vacío. **Today**, **Week**, **Month**, **Year** y **All** eligen el periodo.\n\n**Consultations** tiene los mismos botones de periodo y una fila por consulta: cuándo empezó, su tipo y para qué era, quién preguntó a quién, dónde, cuántos turnos, cómo terminó y el resultado, cuánto costó, qué se preguntó y qué se aconsejó. Una fila que nadie ha decidido todavía — sin resultado, o con uno que caducó — tiene **record…**, que pregunta *Solved*, *Not solved* o *Abandoned* y después una frase opcional para el registro; Escape en cualquiera de los dos pasos la deja abierta. Una consulta fallida no lo tiene, porque no produjo ningún consejo sobre el que dar un veredicto. Se muestran las doscientas más recientes, y la página lo dice cuando hay más.\n\n**What each AI has used** es el gasto, y tiene un artículo propio. **What it keeps missing** cuenta, sobre el periodo que elija, los hallazgos que la IA aceptó — por categoría, por rol de revisor y por proveedor, en las columnas *taken*, *of* y *%* —, porque un hallazgo aceptado es algo que no había visto y que luego reconoció que valía la pena. Bajo los recuentos, *Rejected, and raised again anyway* enumera los desacuerdos que todavía defiende: rechazados con un motivo, y planteados de nuevo por otro revisor.",
    whatCanGoWrong: "**Una pestaña dice que está leyendo hasta que tiene algo**, y después dice qué salió mal si no llega nada, en vez de quedarse en blanco: una pestaña en blanco es también el aspecto de un envío que nunca llegó.\n\n**What it keeps missing lo cuenta el servidor.** Un `coai-mcp` anterior a 0.37.0 no puede dividirlo por periodo, y la pestaña lo dice y muestra todo el tiempo en vez de hacer pasar todo el tiempo por hoy. *Nothing decided in this period* y *Nothing decided yet* son frases distintas: la primera significa que un periodo más amplio, o All, mostraría algo.\n\nUna fecha escrita en From o To es su propio intervalo, así que mientras está puesta no hay ningún botón de periodo marcado en Conversations.",
  },
  "what-each-ai-has-used": {
    title: "Qué ha gastado cada IA: tokens, dinero y tiempo",
    whatItIs: "La pestaña **What each AI has used** de **Show review rounds**. Una barra por proveedor sobre un día, una semana, un mes o un año — **Today**, **Week**, **Month** y **Year**, sobre las barras, eligen cuál, Today por defecto: tokens de entrada y salida, **dinero**, cuántas ejecuciones, cuántas fallaron, tiempo total y medio — y una línea al final que suma todos los proveedores. Los turnos de chat también se cuentan, y tienen su propia sección en esta pestaña: arriba **Reviewers**, una línea, y debajo **Chat** — una tarjeta por proveedor Y modelo, con la forma de las tarjetas de revisores de arriba, porque una conversación cambia de modelo y un precio pertenece al modelo. Cada tarjeta de chat lleva ambos precios, lo que costó en la ventana elegida, lo que ha costado **en todo el tiempo** sea cual sea la ventana de arriba, y dos contadores: **Asked**, cuántas veces se usaron *take the question* y *add the question*, y **Opened**, cuántas veces se abrió un chat por cualquiera de sus seis puertas. Cada sección suma la suya, porque los dos registros los escriben programas distintos y no deben sumarse a ojo. Bajo ambas secciones, una segunda línea y una fila más suman los dos registros, porque «cuánto me ha costado esto» es una sola pregunta la gastara la mitad del producto que la gastara. Los turnos de chat también aparecen, turno a turno, en la pestaña **Conversations** de la misma página.",
    why: "Un panel de revisión gasta dinero real en cada ronda, y la pregunta «cuánto me ha costado este mes» no se responde desde un archivo de sesión: las sesiones se reescriben conforme avanzan las rondas y guardan una rama cada una.",
    setup: "Para los tokens no hay nada que configurar: el servidor añade una línea por revisor a `usage.jsonl` en su directorio de datos, y esta pestaña la lee.\n\nPara el DINERO hay una cosa, y solo usted puede darla: **cuánto cobra este proveedor por millón de tokens, de entrada y de salida**, en la tarjeta de ese proveedor en Settings → Reviewers (**$ / 1M in**, **$ / 1M out**). Este producto no incluye tabla de precios a propósito — una incluida está mal para quien tenga una suscripción plana, mal en cuanto un proveedor cambie un precio, y mal en silencio en ambos casos. Ponga una tarifa y aparece el dinero de ese proveedor; déjela vacía y queda un guion.",
    usage: "**Un revisor que falla también se cuenta.** Una ejecución que quemó noventa segundos y no respondió nada es justo lo que un registro de gasto no debe esconder, así que cada fila lleva su resultado y el número de fallos va junto a los tokens.\n\n**La tilde carga significado.** `$0.42` es lo que cobró un proveedor; `~$0.42` es lo que sale de su propia tarifa. Claude informa su coste, Codex y Antigravity informan solo tokens — así que en esos dos hay tilde o guion, nunca una cifra desnuda. El total mantiene las mitades separadas por lo mismo: se lee `$0.18 + ~$0.31` en vez de sumar un hecho con un cálculo y presentar el resultado como uno de los dos.\n\nPor debajo de un dólar el dinero se muestra con cuatro decimales. Una ronda que costó ocho centésimas de centavo es un número real, y redondearlo a `$0.00` dice que el panel no está contando.\n\n**La ✕ de una tarjeta la borra de este gráfico**, tras preguntar — la tarjeta de un proveedor en *Reviewers*, un par proveedor-modelo en *Chat*. No se borra nada del registro en disco: la tarjeta deja de contar lo ya registrado y vuelve la próxima vez que ese proveedor se ejecute, o que ese modelo responda. La fila de chat *nothing chosen* no tiene ✕, porque no hay ningún par que olvidar.\n\n**Un Team server en el que ha iniciado sesión añade un bloque propio**, bajo su nombre: los tokens, ejecuciones y fallos de sus proveedores tal como los contó el SERVIDOR — él lleva el registro, así que aquí nada lo recalcula — y, cuando ha atendido ambas cosas, cuánto se fue en revisiones y cuánto en conversaciones. Un administrador de ese servidor tiene además **Show the whole company**, que amplía el bloque de su propio uso al de todos y lo devuelve; para cualquier otro el servidor lo rechazaría, así que el botón no se dibuja.",
    whatCanGoWrong: "Los tokens se cuentan por proveedor porque una sola regla sería falsa para al menos uno: Codex mete los tokens en caché DENTRO de la entrada, Claude los informa AL LADO, y en Antigravity los tokens de razonamiento van dentro de la salida. Claude además informa la misma ejecución dos veces con números distintos; se usa el agregado.",
  },
  "questions-waiting": {
    title: "Una pregunta que le espera",
    whatItIs: "Cuando la puerta necesita a una persona, arriba de la barra lateral, en **Active questions**, aparece una tarjeta con la pregunta y los hallazgos que siguen bloqueando — la única tarjeta que tiene una pregunta, con las respuestas de los consultores debajo si las hubo. Se abre un diálogo, aparece un elemento en la barra de estado y el icono del título se pone verde.",
    why: "Detrás de esa pregunta hay una ronda BLOQUEADA. Una notificación que se puede perder no sirve para esto — de ahí las tres superficies, y cerrar el diálogo no pierde nada.",
    setup: "Para el caso corriente no hay nada que configurar: el servidor escribe la pregunta como fichero en el directorio que la extensión ya vigila, y ninguna de las dos mitades abre un puerto. Un caso sí necesita un ajuste. Una ronda que corre en OTRA instalación —una sesión de Claude Code dentro de WSL, por ejemplo— escribe su pregunta en el directorio de datos de AQUELLA instalación, y una ventana que solo vigila el suyo no la muestra nunca mientras la ronda está bloqueada. `coai.alsoWatchDataDirectories` nombra los otros directorios: las preguntas de otra instalación aparecen junto a las propias y la respuesta se escribe junto a la pregunta, donde mira el servidor que preguntó. La pestaña **MCP server** de Settings los enumera bajo *Questions from another installation are also answered here*, y un directorio que no se puede leer se nombra ahí con el motivo: el silencio se vería exactamente igual que una instalación que no ha preguntado nada. Solo se comparten las preguntas; ninguna base de datos se abre a través de la frontera. Desde una ventana de Windows un directorio de WSL debe nombrarse como Windows lo alcanza: `\\\\wsl.localhost\\<distro>\\home\\<user>\\.local\\share\\coai-mcp` — una ruta que empieza por `/` se rechaza explicándolo, en vez de vigilar un directorio que nadie eligió.",
    usage: "Puede responder en el panel, en el diálogo, desde la barra de estado o con **Answer the open question…** — el icono en la barra de título de la barra lateral de ConnectOtherAIs, que pregunta cuál cuando hay más de una esperando y lo dice cuando no hay ninguna. El elemento de la barra de estado abre **Show review rounds**, cuyo bloque **Open questions** tiene un botón **Answer…** en cada pregunta. Todo es la misma acción. Su respuesta vuelve a la IA que preguntó exactamente como usted la dio: nada la traduce, en ninguna de las dos direcciones.",
    whatCanGoWrong: "El veredicto `call_human` también levanta una tarjeta así, de modo que una puerta con las rondas agotadas le alcanza aunque la IA calle. No siempre fue así: antes el veredicto era una instrucción solo para la IA, y una persona podía mirar el panel todo el día sin enterarse de que la habían llamado.",
  },
  "prompts-in-full": {
    title: "Los prompts, completos",
    whatItIs: "El texto completo de cada prompt que este producto envía a un revisor — los cuatro universales, las veinte lentes estrechas, la pasada de convenciones, los tres prompts de documento, el resumen de documento y la revisión de la funcionalidad. Aquí no hay nada parafraseado; esto es lo que lee el modelo.",
    why: "Una revisión que no se puede auditar es una revisión que hay que creer. Saber exactamente qué se preguntó es lo que permite juzgar si una respuesta fue justa — y si un hallazgo con el que no está de acuerdo vino de un modelo malo o de una pregunta mala.",
    setup: "Nada que configurar. Lo impreso abajo se compara con los propios archivos de prompts del servidor mediante un test, así que no puede desviarse de lo que realmente se ejecuta.\n\nEl prompt **conventions** va en un grupo aparte porque es el único prompt de un rol de código propio, Conventions: no es una lente sobre la pregunta de otro rol, sino otra pregunta, que se hace en cada ronda que tenga ese rol. Las reglas llegan con él — los propios `CLAUDE.md`, `AGENTS.md`, `GEMINI.md` y `.claude/rules` del proyecto, leídos del worktree del commit revisado y citados literalmente, hasta 40 KB, y lo que quede fuera se nombra en vez de descartarse en silencio.",
    usage: "Cada prompt termina con la misma disciplina: un hallazgo debe nombrar una situación concreta y el resultado equivocado que produce; cuatro clases de no-hallazgo están nombradas y prohibidas; y se dice expresamente que una lista de hallazgos vacía es una respuesta válida — a un revisor al que se le dice que siempre encuentre algo, siempre encontrará algo.\n\nPuede sobrescribir cualquiera: deje un archivo con el nombre del prompt en `prompts/` dentro del directorio de datos del servidor y gana mientras exista. Bórrelo y vuelve el texto de fábrica.",
    whatCanGoWrong: "Una sobrescritura no se valida. Un prompt que no pide el esquema de hallazgos producirá respuestas que no se pueden parsear, y la ronda informará de ese revisor como no parseable — guardando su respuesta cruda en disco para que vea qué pidió.",
  },
  "the-help-page": {
    title: "Esta página: búsqueda, idioma y tamaño del texto",
    whatItIs: "El ? amarillo del título del panel abre esta ayuda. La lista muestra cada artículo con su primera línea; el campo de arriba busca en todos; el desplegable cambia el idioma; los botones ± cambian el tamaño del texto, y el par de al lado el tono del texto: más claro, o más apagado y cálido. Cada página de ConnectOtherAIs lleva los mismos dos pares junto a su título, y una pulsación en cualquiera de ellos cambia todas las páginas que estén abiertas.",
    why: "Una pestaña Settings con decenas de controles necesita un sitio donde se diga con detalle qué hace cada uno: el pequeño ? junto a un control da una frase, y estas páginas dan las razones que hay detrás. El tamaño del texto está aquí porque la vista no es materia de discusión: cinco pasos en cada sentido son aproximadamente ×1,6 arriba o abajo.",
    setup: "Nada que configurar. El selector de idioma escribe `coai.helpLanguage` y solo afecta a estas páginas — no es el idioma en el que otra IA responde en un chat, que es **Answer in**, en Settings → Chat other AIs. Los botones ± escriben `coai.uiScale` y `coai.textTone`; el cero del tono es el color de su propio tema, así que un control sin tocar no cambia nada. Ambos son ajustes reales, así que se sincronizan con sus otras máquinas.",
    usage: "La búsqueda recorre los títulos Y el texto completo de cada artículo en el idioma mostrado, así que una palabra que recuerde de un párrafo encuentra el artículo donde estaba. Escape cierra un artículo y vuelve a la lista, y Back conserva lo escrito.\n\nUn artículo sin traducir muestra el inglés con una nota visible, no una página en blanco.",
    whatCanGoWrong: "Que una traducción vaya por detrás del inglés es normal y se señala. Lo que no puede pasar es que falte un artículo: un test de cobertura tumba la compilación cuando de un comando o un ajuste no hay nada escrito. Justo por eso esta página no puede convertirse en silencio en la descripción de un producto que ya no existe.",
  },
  "the-protocol": {
    title: "Bajo el capó: el protocolo que sigue su IA",
    whatItIs: "Doce herramientas en orden estricto. `open` abre una sesión para un repositorio y una rama. `review_plan` envía el plan a todos los revisores. `resolve` registra la aceptación o el rechazo de CADA hallazgo. `review_code` hace lo mismo con el diff, con cuatro roles por proveedor. `review_document` es la otra puerta: un DOCUMENTO en lugar de un diff, sin ronda de plan antes y con su propia sesión por documento. `review_feature` es la cuarta puerta, que se llama una vez al final de un plan de tres o más épicas, antes del lanzamiento: cada ronda anterior vio una porción, y esta envía la funcionalidad entera a los revisores que usted marcó para funcionalidades — un plan de menos épicas se registra como *skipped* y no bloquea. `providers` muestra el estado, `status` devuelve al contexto una conversación reanudada, y `ask_human` escala hasta usted. Y antes de él, `ask_consultants`: el consultor de preguntas, en el que cada fila-modelo que usted configuró responde a la pregunta del asistente a la vez, de modo que a usted solo se le pregunta lo que ellos no pudieron resolver (tras los dos primeros lotes de preguntas del plan aceptado, hasta el release; un riesgo para producción le llega de inmediato, con sus respuestas bajo la tarjeta). `consult` y `close_consult` son las dos que no bloquean nada: con `consult` un asistente atascado pregunta al modelo de otro proveedor sobre su árbol de trabajo tal como está, y recibe una respuesta en lugar de un veredicto; con `close_consult` registra cómo terminó esa consulta — *solved*, *not solved* o *abandoned* — una vez que ha verificado el consejo.",
    why: "El orden se sostiene por rechazo, no por buena conducta: `review_code` se niega mientras ninguna ronda de plan haya llegado a *proceed*, de modo que saltarse una etapa es imposible, no «desaconsejable».",
    setup: "Nada que configurar: esto lo maneja su IA. El orden se lo dice justo el fragmento que usted pegó en el repositorio.",
    usage: "Un rechazo exige un motivo, y el motivo se conserva: un hallazgo rechazado no cuenta en las siguientes rondas hasta que un revisor lo vuelva a plantear con un argumento nuevo. Eso es lo que impide que el bucle reabra una decisión que usted ya tomó.",
    whatCanGoWrong: "Una ronda en la que no respondió NADIE no pasa nunca. Un resultado vacío es ausencia de evidencia, no evidencia de ausencia: la puerta llama a una persona en su lugar. Es el único caso en el que «sin hallazgos» no debe significar «aprobado».",
  },
  "where-reviewers-run": {
    title: "Bajo el capó: dónde se ejecuta realmente un revisor",
    whatItIs: "Por defecto, cada revisor se ejecuta en un directorio vacío, tanto en la etapa de plan como en la de código. El interruptor de la etapa de código — lo que recibe un revisor — tiene dos posiciones: Fast le entrega el prompt compuesto y nada que explorar; Full le da además UN git worktree, fijado al commit de la rama, en solo lectura.",
    why: "Fast es el valor por defecto porque se midió, no porque se prefiriera. Sobre un commit, quitar la copia de trabajo hizo que cada modelo alojado encontrara MÁS defectos útiles — de cuatro a ocho, de seis a diez, de seis a siete — con entre la mitad y un tercio de los tokens de entrada, sin ningún hallazgo erróneo en ninguno de ellos, y salieron a la luz tres defectos reales a los que no había llegado ninguna ejecución CON copia de trabajo. Un revisor al que se le da un repositorio gasta su atención en decidir dónde mirar; un revisor al que se le da un diff lee el diff. En la etapa de plan el efecto fue aún más burdo: ocho minutos y todavía ejecutándose, para un documento de quince kilobytes.",
    setup: "Nada que configurar. Los worktrees viven bajo el directorio de datos del servidor y se limpian al abrir una sesión, así que una ronda abortada no deja nada detrás. Full cuesta una extracción por ronda; Fast no cuesta ninguna.",
    usage: "Lo que contiene el prompt no cambia entre los dos: el diff y las reglas escritas de este proyecto los reúne el servidor en ambos casos, así que la única diferencia es si hay un repositorio por el que perderse. Elija Full cuando el significado de un cambio dependa de llamadores que el diff no muestra — y sepa que, en el commit medido, encontró menos. La etapa de plan no tiene interruptor, y su coste dicho sin rodeos: un revisor de plan no puede comprobar que una referencia `file.cs:line` del plan sea real.",
    whatCanGoWrong: "El único reintento que tiene un revisor también se ejecuta en un directorio vacío, por la misma razón: una reparación pide la respuesta con el esquema, no más exploración. Volver a entregarle la copia de trabajo era lo que hacía que una de cada tres rondas de código perdiera un revisor.",
  },
  "when-a-reviewer-fails": {
    title: "Bajo el capó: qué pasa cuando un revisor falla",
    whatItIs: "Seis desenlaces con nombre, y nunca un cero silencioso: respondió, agotó el tiempo, terminó con código distinto de cero, chocó con un límite, no pudo arrancar, o respondió algo que no se puede parsear. Una ronda que pasó con cuatro revisores de seis lo dice así, con nombres.",
    why: "Un panel que no revisó no es un panel que aprobó. Cada ronda incompleta se informa como incompleta, y la frase sobre los revisores nombra quién falló y por qué.",
    setup: "Nada que configurar. Un revisor con límite de peticiones se reintenta una sola vez tras una pausa — salvo que el proveedor haya dicho que el límite es DIARIO, y eso no lo cura ningún reintento.",
    usage: "Un fallo lleva las propias palabras de la CLI, elegidas por contenido y no por posición: la primera línea que anuncia un error, saltándose los marcos de pila y los banners de versión. Para cinco fallos conocidos — CLI retirada, directorio no confiable, binario ausente para la plataforma — se dice QUÉ HACER, no qué se imprimió.",
    whatCanGoWrong: "Una respuesta que no se pudo parsear se guarda en disco bajo `unparseable/` dentro del directorio de datos, y el fallo nombra el fichero. Esto nació porque esa misma respuesta, reproducida a mano, pasaba sin problemas: el mensaje nombraba un síntoma imposible de investigar.",
  },
  "settings-and-the-server": {
    title: "Bajo el capó: cómo llega un ajuste al servidor",
    whatItIs: "Lo que ajusta en la pestaña Settings se escribe en un fichero dentro del directorio de datos del servidor, y el servidor relee ese fichero cada vez que cambia.",
    why: "Antes los ajustes llegaban al servidor solo dentro del bloque de configuración pegado, y cambiar un umbral se convertía en un trámite: copiar el bloque, encontrar la configuración del cliente, pegar, reiniciar. Y solo se aplicaban al arrancar — una brecha invisible desde ambos lados, porque el panel guarda al instante y así lo dice.",
    setup: "Nada que configurar. Un cambio en la pestaña Settings rige desde la SIGUIENTE ronda: ni reinicio ni volver a pegar.",
    usage: "Una variable puesta en la configuración del propio asistente sigue ganando al fichero: es más específica que un fichero que cualquier ventana puede reescribir.\n\nSolo se escribe lo que DIFIERE de los valores por defecto, así que devolver un ajuste a su valor por defecto lo quita del fichero en vez de fijarlo.\n\nAjustes separados por lado: una máquina puede tener varios entornos de trabajo - una ventana local y una o varias distribuciones de WSL - y VS Code les entrega el MISMO archivo de ajustes. Active **Separate settings for each side**, en Settings → This side, y cada lado conserva sus propios valores, sembrados con lo que tenía en ese momento, de modo que nada cambia hasta que edite algo. Para una persona que trabaja para dos empresas en una máquina, eso significa un proxy distinto, una ruta de CLI distinta y una clave de bóveda distinta por lado. El tamaño del texto y el idioma de la ayuda siguen siendo comunes: le pertenecen a usted, no al trabajo.",
    whatCanGoWrong: "Un fichero a medio escribir deja en pie la última configuración que funcionaba. Una lectura rota que diera una lista de proveedores vacía haría fallar a todos los revisores y luego informaría de un panel de acuerdo consigo mismo.",
  },
  "move-your-config": {
    title: "Llevarse la configuración: Export config e Import config",
    whatItIs: "El menú ⋯ de la barra lateral de ConnectOtherAIs → **Export config** escribe en un archivo JSON todo lo que usted cambió: cada ajuste cuyo valor difiere del predeterminado y el texto de cada prompt que escribió. **Import config** lee un archivo así y lo aplica tras una confirmación.",
    why: "Un panel afinado durante semanas — revisores, modelos, umbrales, roles y sus prompts — se reconstruye si no a mano en cada máquina nueva y se comparte con un colega por captura de pantalla.",
    setup: "Nada que configurar. El archivo es JSON legible que puede guardar en un repositorio o enviar a alguien.",
    usage: "La importación dice antes lo que hará: cuántos ajustes y textos de prompt, cuántos de esos textos sustituyen texto que ya tiene, y todo lo que NO aplicará, cada cosa con su motivo. Los ajustes que el archivo no nombra quedan como están, y no se borra nada. Una ruta de CLI que esta máquina ya tiene para un revisor se conserva, porque la exportación omite todas las rutas.",
    whatCanGoWrong: "**Un secreto y la disposición de esta máquina nunca viajan**: la clave de acceso a la bóveda, el directorio de datos, qué lado de la máquina es esta ventana, y cada ruta de CLI. Los tokens no son ajustes y nunca se leen. Las sustituciones por lado ni se exportan ni se cambian — solo el valor compartido.\n\nUn archivo de otra versión de esta extensión se rechaza con una frase en vez de leerse a medias, y un ajuste que esta compilación no conoce se rechaza por su nombre mientras el resto se aplica. Si una escritura falla a mitad, todo lo que la importación ya había cambiado se restaura, y el aviso lo dice — o nombra lo que no pudo restaurarse.",
  },
  "the-audit-log": {
    title: "Bajo el capó: el registro de auditoría",
    whatItIs: "Un fichero de log por arranque del servidor, en `logs/<día>/` dentro de la misma carpeta donde el servidor guarda todo lo demás — vea *Dónde viven sus datos*. Contiene el reparto de cada ronda, el arranque y la respuesta de cada revisor con tokens y dinero, cada negativa como aviso con su motivo, y cada hallazgo con su procedencia.",
    why: "El resumen de una ronda es deliberadamente una frase, y una frase no responde a «por qué falló ese revisor». Esa pregunta surgió dos veces en una puerta real, y las dos veces no había nada que responder.",
    setup: "Nada que configurar. Los niveles vienen de la configuración y no de los puntos de llamada, y cada arranque escribe un fichero nuevo — no uno por día, porque casi siempre se pregunta qué hizo AQUELLA ejecución.",
    usage: "En nivel debug se escribe la línea de comandos exacta de cada revisor: esa es la diferencia entre «saber que se preguntó al proveedor» y «pegar el comando en una terminal y ver la misma negativa».",
    whatCanGoWrong: "El log es el único sitio donde algunas cosas quedan registradas. No rota ni se recorta: un año de trabajo denso es una carpeta de ficheros pequeños — no es un problema, pero limpiarla le toca a usted.",
  },
  "where-your-data-lives": {
    title: "Dónde viven sus datos, y cómo conservarlos",
    whatItIs: "Una carpeta guarda todo lo que este producto recuerda: la base de datos de rondas, las sesiones, sus chats con sus imágenes, los prompts que editó, el libro de gastos y los registros de auditoría. Por defecto es `%LOCALAPPDATA%\\coai-mcp` en Windows y `~/.local/share/coai-mcp` en el resto. La pestaña **MCP server** de Settings nombra la carpeta que lee esta ventana.",
    why: "La carpeta por defecto vive en el disco del sistema, y el disco del sistema es justo lo que se formatea. Apúntela a una unidad de red o a un NAS y su historial sobrevive al sistema operativo que tiene encima: reinstala, instala de nuevo el servidor MCP, elige la misma carpeta, y todas las rondas que ha hecho siguen ahí. La misma carpeta pueden compartirla una ventana de Windows y otra de WSL en la misma máquina.",
    setup: "La instalación del servidor MCP pregunta, la primera vez en cada lado de una máquina: conservar la carpeta por defecto o elegir una. Elegir una carpeta que ya contiene una base de datos la ADOPTA — de eso se trata, y así una máquina reinstalada recupera su propio historial. También puede fijarlo usted en Configuración: `coai.dataDirectory` para la carpeta y `coai.dataSide` para el nombre de esta instalación dentro de ella. Ambos se guardan por lado de la máquina, porque el mismo NAS es `Z:\\coai` en una ventana de Windows y `/mnt/z/coai` en una de WSL. Después la pestaña **MCP server** de Settings lleva **Change where your data lives…** y **Move what is here to another folder…**, y la paleta de comandos tiene las mismas dos entradas.",
    usage: "Un servidor solo conoce la carpeta por la entrada de cliente que lo arranca, así que el bloque que *Install the MCP server…* copia a su portapapeles ya la lleva: péguelo una vez, reinicie su asistente, y ambas mitades leen el mismo sitio.\n\nDé un nombre a un lado cuando dos instalaciones comparten una carpeta: cada una guarda dentro su propia base de datos, sus sesiones y sus inicios de sesión. Déjelo vacío cuando solo esta instalación usa esa carpeta.",
    whatCanGoWrong: "El panel y el servidor pueden acabar leyendo carpetas distintas — eso es lo que significa una lista de rondas vacía mientras su asistente dice que está revisando. La pestaña MCP server nombra la carpeta que lee ESTA VENTANA y entrega las dos líneas que hacen que un servidor coincida con ella.\n\nUn nombre de lado puede llevar minúsculas, dígitos, punto, guion y guion bajo. Cualquier otra cosa se rechaza en vez de ignorarse en silencio, y el servidor no arranca con ella: volver a la carpeta compartida pondría todas las instalaciones sobre una sola base de datos, lo contrario de para lo que sirve un lado.\n\nMudar una carpeta que ya tiene cosas es una copia que se hace con nada en marcha, y es más que la base de datos: las sesiones, los chats y sus libros, los prompts que editó, el libro de gastos y los registros de auditoría y los logs se mudan con ella — con una excepción: si le ha dado un nombre de lado a esta instalación, el servidor escribe sus logs en la carpeta SUPERIOR al lado, así que una mudanza no los alcanza y lo dice antes de empezar. Deje atrás los worktrees temporales y los tokens de sesión — un token pertenece al lado que lo obtuvo.\n\n**Move your data to another folder** — el botón **Move what is here to another folder…** de la misma pestaña — hace esa copia por usted: se niega mientras algo siga escribiendo, se niega ante una carpeta que ya tiene una historia propia, copia, y luego vuelve a leer la carpeta nueva y la compara con la vieja antes de apuntar esta ventana allí. No borra nada. **Delete the old data folder** es una acción aparte, y sigue negada hasta que una mudanza cuadre: una copia que no cuadró es una copia para la que la carpeta vieja puede ser el único sitio donde algo aún existe.",
  },
};
